// Normalisation/fuzzy-matching de noms d'équipes — utilisé pour fusionner les cotes
// scrapées (Unibet/Betclic/Winamax) avec les fixtures (FD leagues + CDM)
const normTeam = s => {
  let base = (s || '').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    // ø/å/æ (25 août 2026, cas Tromsø) ne sont PAS des lettres accentuées décomposables par NFD —
    // ce sont des lettres distinctes en Unicode, donc jamais nettoyées par le .normalize ci-dessus
    // contrairement à ö/ü/ä (qui eux se décomposent bien en base+diacritique).
    .replace(/ø/g, 'o').replace(/å/g, 'a').replace(/æ/g, 'ae');
  // Alias mot-à-mot (25 août 2026, cas Rapid Vienne/Omonia Nicosie) — COUNTRY_ALIASES/BRESIL_TEAM_ALIASES
  // n'étaient cherchées que sur la CHAÎNE ENTIÈRE une fois les espaces supprimés, donc ne marchaient
  // que pour un nom sans préfixe (ou dont le préfixe est dans la liste de tokens supprimés plus bas,
  // ex: "FC Barcelone" → "fc" supprimé → chaîne entière = "barcelone"). Un préfixe hors de cette liste
  // ("Rapid Vienne", "Omonia Nicosie") ne laissait jamais la chaîne entière égale à l'alias. Remplace
  // maintenant chaque mot individuellement avant la concaténation finale — la recherche sur la chaîne
  // entière ci-dessous reste en plus pour les alias multi-mots déjà composés (ex: "realracingdesantander").
  base = base.replace(/[a-z]+/g, w => COUNTRY_ALIASES[w] || BRESIL_TEAM_ALIASES[w] || w);
  base = base
    .replace(/\b(as|fc|sc|rc|ogc|afc|ac|stade|club|island|islands)\b/g, '')
    .replace(/\bst\b/g, 'saint')
    .replace(/\butd\b/g, 'united') // "Leeds Utd" (Betclic) vs "Leeds United" (Pinnacle/FD)
    .replace(/[^a-z]/g, '');
  return COUNTRY_ALIASES[base] || BRESIL_TEAM_ALIASES[base] || base;
};
const fuzzy = (a, b) => {
  if (!a || !b) return false;
  const na = normTeam(a), nb = normTeam(b);
  return na.includes(nb) || nb.includes(na);
};

// ── Alertes football BTTS + Over/Under (Poisson) ─────────────────────────────
// Buts/équipe/match attendus — référence pour les facteurs attaque/défense
// bresil : calculé le 17 juillet 2026 sur le classement BSA en cours (475 buts / 358 matchs joués = 1.327)
const FB_LEAGUE_AVG_GOALS = { ligue1: 1.35, pl: 1.45, laliga: 1.35, bundes: 1.55, seriea: 1.35, bresil: 1.33 };

// ── Blessures foot via api-football (22 juillet 2026, plan Pro souscrit) ──────────────────────
// Pénalise le modèle Poisson quand un attaquant ou un gardien/défenseur clé est annoncé absent —
// jusqu'ici (`computeLambdas`) le modèle ne voyait QUE les stats but/équipe, aveugle à toute
// absence individuelle, contrairement au basket (RotoWire + calcKeyPlayerOutPenalty). Couvre les
// 5 grands championnats + Brasileirão + LDC/Europa/Conference (23 juillet 2026 — vérifié en direct
// que /teams et /injuries acceptent ces 3 competitionId exactement comme un championnat domestique,
// aucun code séparé nécessaire). CDM non concernée (pas d'id api-football mappé, seule compétition
// sans club — la logique attaquant/gardien clé ne s'y applique pas de la même façon).
const FOOTBALL_API_BASE = 'https://v3.football.api-sports.io';
const FOOTBALL_API_LEAGUE_IDS = { ligue1: 61, pl: 39, laliga: 140, bundes: 78, seriea: 135, bresil: 71, europa: 3, conference: 848, champions: 2 };
// Semaphore + retry sur rateLimit (22 juillet 2026) — même pattern que bballFetch (api-sports.io
// basketball, ~ligne 3852) : le xG (jusqu'à ~17 appels/match : liste des derniers matchs + stats
// par match, x2 équipes) déclenchait le rate limit 300 req/min du plan Pro dès 2-3 matchs traités
// à la suite sans throttle. Trouvé en isolant le bug dans un script à part (repro_xg.js, jamais
// commité) plutôt qu'en multipliant les redémarrages du serveur en direct.
let _footballApiActive = 0;
const _footballApiQueue = [];
function footballApiRelease() {
  _footballApiActive--;
  if (_footballApiQueue.length > 0) _footballApiQueue.shift()();
}
async function _footballApiFetchRaw(url) {
  if (_footballApiActive >= 5) await new Promise(res => _footballApiQueue.push(res));
  _footballApiActive++;
  try {
    const r = await fetch(url, { headers: { 'x-apisports-key': process.env.FOOTBALL_API_KEY }, signal: AbortSignal.timeout(10000) });
    if (!r.ok) throw new Error(`football-api ${r.status} ${url}`);
    const j = await r.json();
    const errCount = Array.isArray(j.errors) ? j.errors.length : Object.keys(j.errors || {}).length;
    if (errCount > 0) {
      // Vérifié en direct le 29 juillet 2026 : quand le quota journalier est dépassé, l'API renvoie
      // quand même x-ratelimit-requests-remaining avec une valeur périmée/non décrémentée (ex: 7499
      // alors que tout est bloqué) — ne jamais faire confiance à ce header en présence d'une erreur,
      // sinon le Dashboard affiche un quota faussement disponible pendant que tout échoue en silence.
      if (j.errors?.requests) _footballApiQuota = { remaining: 0, limit: _footballApiQuota.limit, ts: Date.now(), blocked: true };
      throw new Error(`football-api errors ${JSON.stringify(j.errors)} — ${url}`);
    }
    _captureFootballApiQuota(r);
    return j;
  } finally { footballApiRelease(); }
}
async function footballApiFetch(url, attempt = 0) {
  if (_footballApiPaused) throw new Error('football-api paused (pause manuelle)');
  try {
    return await _footballApiFetchRaw(url);
  } catch (e) {
    // Fix 23 juillet 2026 : ce retry ne reconnaissait que le rate-limit "doux" (réponse 200 avec
    // un champ errors.rateLimit dans le JSON) — jamais le vrai statut HTTP 429, que l'API renvoie
    // aussi (confirmé en direct : tous les appels Europa League échouaient silencieusement avec
    // "football-api 429 ...", jamais retentés, faute de correspondre à /rateLimit/i). Les deux
    // formes déclenchent maintenant le même retry avec backoff.
    if ((/rateLimit/i.test(e.message) || /football-api 429\b/.test(e.message)) && attempt < 3) {
      await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
      return footballApiFetch(url, attempt + 1);
    }
    throw e;
  }
}
// Saison api-football pour une date donnée : ligues européennes = année de début (août-mai,
// ex. mai 2024 → saison "2023"), Brasileirão = année civile du match (calendrier janvier-décembre).
// Vérifié en direct le 22 juillet 2026 sur les 6 championnats avant d'écrire cette règle.
function footballApiSeasonForDate(leagueKey, dateStr) {
  const d = new Date(dateStr);
  if (leagueKey === 'bresil') return d.getUTCFullYear();
  return d.getUTCMonth() + 1 >= 7 ? d.getUTCFullYear() : d.getUTCFullYear() - 1;
}
const _footballInjuriesCache = {}; // `${leagueKey}_${YYYY-MM-DD}` → { data, ts }
async function fetchFootballInjuriesForDate(leagueKey, dateOnly) {
  const cacheKey = `${leagueKey}_${dateOnly}`;
  const cached = _footballInjuriesCache[cacheKey];
  if (cached && Date.now() - cached.ts < CACHE_6H) return cached.data;
  const leagueId = FOOTBALL_API_LEAGUE_IDS[leagueKey];
  if (!leagueId || !process.env.FOOTBALL_API_KEY) return [];
  try {
    const season = footballApiSeasonForDate(leagueKey, dateOnly);
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/injuries?league=${leagueId}&season=${season}&date=${dateOnly}`);
    // Dédup par joueur+fixture — l'API renvoie parfois la même entrée en double (observé le 22
    // juillet 2026 sur Brasileirão, jamais expliqué côté doc, juste vérifié et neutralisé ici).
    const seen = new Set();
    const list = (j.response || []).filter(x => {
      const k = `${x.player?.id}_${x.fixture?.id}`;
      if (seen.has(k) || !x.player?.id) return false;
      seen.add(k);
      return true;
    }).map(x => ({ playerId: x.player.id, playerName: x.player.name, teamName: x.team?.name }));
    _footballInjuriesCache[cacheKey] = { data: list, ts: Date.now() };
    return list;
  } catch { return []; }
}
const _footballPlayerStatsCache = {}; // `${playerId}_${leagueId}_${season}` → { data, ts }
async function fetchFootballPlayerSeasonStats(playerId, leagueId, season) {
  const cacheKey = `${playerId}_${leagueId}_${season}`;
  const cached = _footballPlayerStatsCache[cacheKey];
  if (cached && Date.now() - cached.ts < CACHE_6H) return cached.data;
  if (!process.env.FOOTBALL_API_KEY) return null;
  try {
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/players?id=${playerId}&season=${season}&league=${leagueId}`);
    const stat = j.response?.[0]?.statistics?.[0];
    if (!stat) return null;
    const data = {
      position: stat.games?.position ?? null,
      goalsAssists: (stat.goals?.total ?? 0) + (stat.goals?.assists ?? 0),
      appearances: stat.games?.appearences ?? 0,
    };
    _footballPlayerStatsCache[cacheKey] = { data, ts: Date.now() };
    return data;
  } catch { return null; }
}
// Blessures actuelles d'une équipe, indépendamment d'une fixture précise (28 juillet 2026,
// outrights) — réutilise fetchFootballInjuriesForDate/fetchFootballPlayerSeasonStats et les mêmes
// seuils FB_KEY_* que computeFootballInjuryPenalties (déclarés juste après), mais pour UNE équipe
// à la date du jour plutôt qu'une paire domicile/extérieur pour un match précis. Pas de nouveau
// scraping — mêmes fonctions bas niveau, juste un filtrage différent.
async function getTeamCurrentInjuryPenaltyFootball(leagueKey, teamName) {
  const neutral = { attackPenalty: 1, defensePenalty: 1 };
  const leagueId = FOOTBALL_API_LEAGUE_IDS[leagueKey];
  if (!leagueId) return neutral;
  const dateOnly = new Date().toISOString().slice(0, 10);
  const injuries = await fetchFootballInjuriesForDate(leagueKey, dateOnly);
  const teamInjuries = injuries.filter(x => fuzzy(x.teamName, teamName));
  if (!teamInjuries.length) return neutral;

  const season = footballApiSeasonForDate(leagueKey, dateOnly);
  const penalty = { ...neutral };
  for (const p of teamInjuries) {
    const stats = await fetchFootballPlayerSeasonStats(p.playerId, leagueId, season);
    if (!stats) continue;
    if (stats.goalsAssists >= FB_KEY_ATTACKER_GOALS_ASSISTS) penalty.attackPenalty = Math.min(penalty.attackPenalty, FB_ATTACK_OUT_PENALTY);
    if (stats.position === 'Goalkeeper' && stats.appearances >= FB_KEY_DEFENDER_APPEARANCES) penalty.defensePenalty = Math.max(penalty.defensePenalty, FB_DEFENSE_OUT_PENALTY);
  }
  return penalty;
}
// Seuils "joueur clé" — valeurs de départ non calibrées sur nos propres données (même statut que
// DIXON_COLES_RHO/SHRINK_K, computeFootball.js) : un attaquant/passeur avec ≥8 buts+passes cette
// saison, ou un gardien/défenseur avec ≥10 titularisations, compte comme clé. À affiner à l'usage.
const FB_KEY_ATTACKER_GOALS_ASSISTS = 8;
const FB_KEY_DEFENDER_APPEARANCES   = 10;
const FB_ATTACK_OUT_PENALTY  = 0.90; // -10% sur le facteur attaque si l'attaquant/passeur clé est absent
const FB_DEFENSE_OUT_PENALTY = 1.12; // +12% sur le facteur défense si le gardien/défenseur clé est absent
async function computeFootballInjuryPenalties(leagueKey, dateStr, homeTeamName, awayTeamName) {
  const neutral = { homeAttackPenalty: 1, homeDefensePenalty: 1, awayAttackPenalty: 1, awayDefensePenalty: 1 };
  const leagueId = FOOTBALL_API_LEAGUE_IDS[leagueKey];
  if (!leagueId) return neutral;
  const dateOnly = new Date(dateStr).toISOString().slice(0, 10);
  const injuries = await fetchFootballInjuriesForDate(leagueKey, dateOnly);
  if (!injuries.length) return neutral;

  const side = injuries.some(x => fuzzy(x.teamName, homeTeamName)) || injuries.some(x => fuzzy(x.teamName, awayTeamName))
    ? { home: injuries.filter(x => fuzzy(x.teamName, homeTeamName)), away: injuries.filter(x => fuzzy(x.teamName, awayTeamName)) }
    : null;
  if (!side || (!side.home.length && !side.away.length)) return neutral;

  const season = footballApiSeasonForDate(leagueKey, dateStr);
  const penalty = { ...neutral };
  for (const [team, players] of [['home', side.home], ['away', side.away]]) {
    for (const p of players) {
      const stats = await fetchFootballPlayerSeasonStats(p.playerId, leagueId, season);
      if (!stats) continue;
      if (stats.goalsAssists >= FB_KEY_ATTACKER_GOALS_ASSISTS) {
        penalty[`${team}AttackPenalty`] = Math.min(penalty[`${team}AttackPenalty`], FB_ATTACK_OUT_PENALTY);
        _bgLog.push(`football injury: ${p.playerName} (${team}, ${p.teamName}) attaquant clé absent — ${stats.goalsAssists} B+PD cette saison`);
      }
      if (stats.position === 'Goalkeeper' && stats.appearances >= FB_KEY_DEFENDER_APPEARANCES) {
        penalty[`${team}DefensePenalty`] = Math.max(penalty[`${team}DefensePenalty`], FB_DEFENSE_OUT_PENALTY);
        _bgLog.push(`football injury: ${p.playerName} (${team}, ${p.teamName}) gardien titulaire absent — ${stats.appearances} matchs cette saison`);
      }
    }
  }
  return penalty;
}

// ── xG foot via api-football (22 juillet 2026) — remplace les buts bruts par du xG (expected
// goals) sur les entrées de computeLambdas quand c'est possible : le xG lisse la variance d'un
// match à l'autre (un 3-0 chanceux à 0.9 xG ne gonfle pas artificiellement l'attaque), donc un λ
// plus stable. Dégrade proprement sur les buts bruts déjà en place (f.homeGF/etc.) si l'équipe
// n'est pas trouvée côté api-football ou si l'échantillon xG est trop court — jamais bloquant.
const FB_XG_RECENT_GAMES = 8; // nb de matchs récents moyennés — pas calibré, même statut que SHRINK_K
const FB_XG_MIN_GAMES    = 3; // sous ce seuil, échantillon jugé trop court, fallback buts bruts
const _footballTeamIdCache = {}; // `${leagueKey}_${season}` → { data: {apiTeamName: id}, ts }
async function fetchFootballTeamIds(leagueKey, season) {
  const cacheKey = `${leagueKey}_${season}`;
  const cached = _footballTeamIdCache[cacheKey];
  if (cached && Date.now() - cached.ts < 24 * CACHE_6H) return cached.data;
  const leagueId = FOOTBALL_API_LEAGUE_IDS[leagueKey];
  if (!leagueId || !process.env.FOOTBALL_API_KEY) return {};
  try {
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/teams?league=${leagueId}&season=${season}`);
    const map = {};
    for (const t of (j.response || [])) if (t.team?.name && t.team?.id) map[t.team.name] = t.team.id;
    _footballTeamIdCache[cacheKey] = { data: map, ts: Date.now() };
    return map;
  } catch { return {}; }
}
const resolveFootballApiTeamId = (teamMap, ourTeamName) => {
  for (const [apiName, id] of Object.entries(teamMap)) if (fuzzy(apiName, ourTeamName)) return id;
  return null;
};
// Persisté sur disque + TTL allongé 6h→24h (19 août 2026, quota FOOTBALL_API_KEY épuisé) — chaque
// cache-miss coûte jusqu'à 9 appels (1 liste de matchs + 8 fixtures/statistics), ×2 équipes par
// match. Le cache n'était QUE en mémoire : chaque redémarrage backend (fréquent en dev, `--watch`)
// le vidait entièrement et forçait un refetch complet au prochain cycle — plus gros contributeur
// réel à l'épuisement que le TTL lui-même. Le xG récent d'une équipe ne bouge de toute façon pas
// plus d'1x/jour (au plus un match joué), 24h est largement suffisant.
const FB_XG_CACHE_TTL = 24 * 3600_000;
const FB_XG_CACHE_FILE = join(CACHE_DIR, 'football_team_xg.json');
let _footballTeamXGCache = {}; // `${teamApiId}_${leagueId}_${season}` → { data, ts }
try { if (existsSync(FB_XG_CACHE_FILE)) _footballTeamXGCache = JSON.parse(readFileSync(FB_XG_CACHE_FILE, 'utf8')); } catch {}
const _saveFootballTeamXGCache = () => { try { writeFileSync(FB_XG_CACHE_FILE, JSON.stringify(_footballTeamXGCache), 'utf8'); } catch {} };
async function fetchTeamRecentXG(teamApiId, leagueId, season) {
  const cacheKey = `${teamApiId}_${leagueId}_${season}`;
  const cached = _footballTeamXGCache[cacheKey];
  if (cached && Date.now() - cached.ts < FB_XG_CACHE_TTL) return cached.data;
  if (!process.env.FOOTBALL_API_KEY) return null;
  try {
    const fj = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures?team=${teamApiId}&league=${leagueId}&season=${season}&last=${FB_XG_RECENT_GAMES}&status=FT`);
    const fixtures = fj.response || [];
    if (fixtures.length < FB_XG_MIN_GAMES) return null;
    // Tirs/possession (22 juillet 2026) — capturés au passage sur la MÊME réponse déjà tirée pour
    // le xG (aucun appel supplémentaire), pour alimenter le panneau "Statistiques saison" côté
    // MatchDetailPage (Tirs/match, Tirs cadrés/match, Possession), jusque-là toujours à 0 faute de
    // source (voir GET /api/football/teamxgstats plus bas).
    let xgFor = 0, xgAgainst = 0, shots = 0, shotsOnTarget = 0, possession = 0, counted = 0;
    for (const fx of fixtures) {
      const sj = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures/statistics?fixture=${fx.fixture.id}`).catch(() => null);
      if (!sj) continue;
      const teams = sj.response || [];
      const us   = teams.find(t => t.team?.id === teamApiId);
      const them = teams.find(t => t.team?.id !== teamApiId);
      const usXG   = us?.statistics?.find(s => s.type === 'expected_goals')?.value;
      const themXG = them?.statistics?.find(s => s.type === 'expected_goals')?.value;
      if (usXG == null || themXG == null) continue;
      xgFor += parseFloat(usXG); xgAgainst += parseFloat(themXG); counted++;
      const usTotalShots = us?.statistics?.find(s => s.type === 'Total Shots')?.value;
      const usShotsOnGoal = us?.statistics?.find(s => s.type === 'Shots on Goal')?.value;
      const usPossession = us?.statistics?.find(s => s.type === 'Ball Possession')?.value;
      if (usTotalShots != null) shots += parseFloat(usTotalShots);
      if (usShotsOnGoal != null) shotsOnTarget += parseFloat(usShotsOnGoal);
      if (usPossession != null) possession += parseFloat(String(usPossession).replace('%', ''));
    }
    if (counted < FB_XG_MIN_GAMES) return null;
    const data = {
      xgFor: xgFor / counted, xgAgainst: xgAgainst / counted, games: counted,
      shotsPerGame: shots / counted, shotsOnTarget: shotsOnTarget / counted, possession: possession / counted,
    };
    _footballTeamXGCache[cacheKey] = { data, ts: Date.now() };
    _saveFootballTeamXGCache();
    return data;
  } catch { return null; }
}
// Reconstitue homeGF/homeGA/homePlayed (etc.) attendus par computeLambdas à partir des moyennes
// xG — même conversion moyenne×matchs déjà utilisée pour la CDM (teamstats renvoie des moyennes,
// computeLambdas attend des totaux qu'il redivise lui-même par `played`).
async function tryGetFootballXGInputs(leagueKey, dateStr, homeTeamName, awayTeamName) {
  const leagueId = FOOTBALL_API_LEAGUE_IDS[leagueKey];
  if (!leagueId) return null;
  const season = footballApiSeasonForDate(leagueKey, dateStr);
  const teamMap = await fetchFootballTeamIds(leagueKey, season);
  const homeId = resolveFootballApiTeamId(teamMap, homeTeamName);
  const awayId = resolveFootballApiTeamId(teamMap, awayTeamName);
  if (!homeId || !awayId) return null;
  const [homeXG, awayXG] = await Promise.all([
    fetchTeamRecentXG(homeId, leagueId, season),
    fetchTeamRecentXG(awayId, leagueId, season),
  ]);
  if (!homeXG || !awayXG) return null;
  return {
    homeGF: homeXG.xgFor * homeXG.games, homeGA: homeXG.xgAgainst * homeXG.games, homePlayed: homeXG.games,
    awayGF: awayXG.xgFor * awayXG.games, awayGA: awayXG.xgAgainst * awayXG.games, awayPlayed: awayXG.games,
    homeAvgXG: homeXG.xgFor, awayAvgXG: awayXG.xgFor,
  };
}

// ── Europa League / Conference League via api-football (23 juillet 2026) ─────────────────────
// Contrairement aux 5 grands championnats/Brasileirão (une seule ligue, historique propre), les
// clubs de ces 2 compétitions viennent de dizaines de championnats différents (Qarabağ, Tromsø,
// Hammarby...) — aucune notion de "classement/stats de LA compétition" exploitable en tours de
// qualification (chaque club n'y a joué que 0-1 match cette saison). Même défi que la CDM (équipes
// hétérogènes, peu de données propres à la compétition) → même solution : forme récente réelle de
// chaque club, tous matchs confondus (amicaux + qualifs + championnat domestique), via l'endpoint
// api-football `/fixtures?team=X` (pas de filtre `league=`, contrairement à fetchTeamRecentXG plus
// haut qui est volontairement scopé à UNE ligue pour les 5 grands championnats).
// Réactivation progressive (23 juillet 2026, après fix BETCLIC_EXTRAS_WINDOW_MS) — Europa League
// seule d'abord (`EU_CLUB_COMP_ENABLED`), un cycle contrôlé à la fois. Conference League (43 matchs)
// rejoint la liste une fois Europa confirmée propre.
const EU_CLUB_ALERTS_ENABLED = true;
const EU_CLUB_COMP_ENABLED = { europa: true, conference: true, champions: true };
const EU_CLUB_COMP_IDS = { europa: 3, conference: 848, champions: 2 };
const EU_CLUB_AVG_GOALS = 1.30; // buts/équipe/match attendus, valeur de départ non calibrée (même statut que CDM_AVG_GOALS)
// Fallback si le pool d'équipes programmées n'a pas assez de stats valides (mécanisme identique à CDM_AVG_GF/GA)
const EU_CLUB_AVG_GF = 1.45;
const EU_CLUB_AVG_GA = 1.15;
// Persisté sur disque (29 août 2026) — même correctif déjà fait pour fetchTeamRecentXG (5 grands
// championnats, FB_XG_CACHE_FILE) : un cache uniquement en mémoire est vidé à chaque redémarrage
// backend (fréquent en dev, `--watch`), forçant un refetch complet peu importe le TTL par ailleurs
// correct — identifié comme le principal contributeur restant à l'écart de quota basket/foot.
const EU_CLUB_FORM_CACHE_FILE = join(CACHE_DIR, 'eu_club_form.json');
let _euClubFormCache = {}; // `${teamApiId}_${season}` → { data: {gf, ga, games}, ts }
try { if (existsSync(EU_CLUB_FORM_CACHE_FILE)) _euClubFormCache = JSON.parse(readFileSync(EU_CLUB_FORM_CACHE_FILE, 'utf8')); } catch {}
const _saveEuClubFormCache = () => { try { writeFileSync(EU_CLUB_FORM_CACHE_FILE, JSON.stringify(_euClubFormCache), 'utf8'); } catch {} };
async function fetchClubRecentForm(teamApiId, season) {
  const cacheKey = `${teamApiId}_${season}`;
  const cached = _euClubFormCache[cacheKey];
  // Aligné sur FB_XG_CACHE_TTL (24h, 25 août 2026) — était 6h, 4x plus de rafraîchissements que
  // l'équivalent 5 grands championnats (fetchTeamRecentXG) pour la même donnée (forme sur les 8
  // derniers matchs, qui ne bouge pas en 6h) — contributeur réel à l'écart de quota basket/foot.
  if (cached && Date.now() - cached.ts < FB_XG_CACHE_TTL) return cached.data;
  if (!process.env.FOOTBALL_API_KEY) return null;
  try {
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures?team=${teamApiId}&season=${season}&last=8&status=FT`);
    const fixtures = j.response || [];
    if (fixtures.length < 3) return null; // échantillon jugé trop court (même seuil que FB_XG_MIN_GAMES)
    let gf = 0, ga = 0, counted = 0;
    for (const fx of fixtures) {
      const isHome = fx.teams?.home?.id === teamApiId;
      const gFor = isHome ? fx.goals?.home : fx.goals?.away;
      const gAgainst = isHome ? fx.goals?.away : fx.goals?.home;
      if (gFor == null || gAgainst == null) continue;
      gf += gFor; ga += gAgainst; counted++;
    }
    if (counted < 3) return null;
    const data = { gf, ga, games: counted };
    _euClubFormCache[cacheKey] = { data, ts: Date.now() };
    _saveEuClubFormCache();
    return data;
  } catch { return null; }
}

// xG toutes compétitions confondues (23 juillet 2026) — même principe que fetchTeamRecentXG (5
// grands championnats) mais sans filtre `league=`, pour la même raison que fetchClubRecentForm
// ci-dessus (les clubs Europa/Conference n'ont pas assez de matchs DANS cette compétition cette
// saison pour un calcul fiable). Alimente le panneau "Statistiques saison" de MatchDetailPage.jsx.
// Persisté sur disque (29 août 2026) — même correctif que fetchClubRecentForm ci-dessus.
const EU_CLUB_XG_CACHE_FILE = join(CACHE_DIR, 'eu_club_xg.json');
let _euClubXGCache = {}; // `${teamApiId}_${season}` → { data, ts }
try { if (existsSync(EU_CLUB_XG_CACHE_FILE)) _euClubXGCache = JSON.parse(readFileSync(EU_CLUB_XG_CACHE_FILE, 'utf8')); } catch {}
const _saveEuClubXGCache = () => { try { writeFileSync(EU_CLUB_XG_CACHE_FILE, JSON.stringify(_euClubXGCache), 'utf8'); } catch {} };
async function fetchClubRecentXG(teamApiId, season) {
  const cacheKey = `${teamApiId}_${season}`;
  const cached = _euClubXGCache[cacheKey];
  // Aligné sur FB_XG_CACHE_TTL (24h, 25 août 2026) — était 6h alors que fetchTeamRecentXG (5 grands
  // championnats) est déjà à 24h pour la même donnée. Coût élevé par appel (1 /fixtures + jusqu'à 8
  // /fixtures/statistics = 9 requêtes/équipe), et les coupes d'Europe font défiler beaucoup plus
  // d'équipes distinctes en tours de qualif que les 5 championnats stables — principal contributeur
  // identifié à l'écart de quota basket (149/7500) vs foot (6058/7500, 81%) le 25 août.
  if (cached && Date.now() - cached.ts < FB_XG_CACHE_TTL) return cached.data;
  if (!process.env.FOOTBALL_API_KEY) return null;
  try {
    const fj = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures?team=${teamApiId}&season=${season}&last=${FB_XG_RECENT_GAMES}&status=FT`);
    const fixtures = fj.response || [];
    if (fixtures.length < FB_XG_MIN_GAMES) return null;
    let xgFor = 0, xgAgainst = 0, shots = 0, shotsOnTarget = 0, possession = 0, counted = 0;
    for (const fx of fixtures) {
      const sj = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures/statistics?fixture=${fx.fixture.id}`).catch(() => null);
      if (!sj) continue;
      const teams = sj.response || [];
      const us   = teams.find(t => t.team?.id === teamApiId);
      const them = teams.find(t => t.team?.id !== teamApiId);
      const usXG   = us?.statistics?.find(s => s.type === 'expected_goals')?.value;
      const themXG = them?.statistics?.find(s => s.type === 'expected_goals')?.value;
      if (usXG == null || themXG == null) continue;
      xgFor += parseFloat(usXG); xgAgainst += parseFloat(themXG); counted++;
      const usTotalShots  = us?.statistics?.find(s => s.type === 'Total Shots')?.value;
      const usShotsOnGoal = us?.statistics?.find(s => s.type === 'Shots on Goal')?.value;
      const usPossession  = us?.statistics?.find(s => s.type === 'Ball Possession')?.value;
      if (usTotalShots != null) shots += parseFloat(usTotalShots);
      if (usShotsOnGoal != null) shotsOnTarget += parseFloat(usShotsOnGoal);
      if (usPossession != null) possession += parseFloat(String(usPossession).replace('%', ''));
    }
    if (counted < FB_XG_MIN_GAMES) return null;
    const data = {
      xgFor: xgFor / counted, xgAgainst: xgAgainst / counted, games: counted,
      shotsPerGame: shots / counted, shotsOnTarget: shotsOnTarget / counted, possession: possession / counted,
    };
    _euClubXGCache[cacheKey] = { data, ts: Date.now() };
    _saveEuClubXGCache();
    return data;
  } catch { return null; }
}
// Résout l'id api-football d'un club depuis le cache de matchs Europa/Conference déjà chargé
// (pas de "liste des équipes de la compétition" exploitable comme pour les 5 championnats, cf.
// fetchFootballTeamIds — on réutilise simplement ce qu'on a déjà côté fixtures).
function resolveEuClubTeamId(compKey, teamName) {
  const matches = _euClubMatchesCache[compKey]?.data?.matches || [];
  for (const m of matches) {
    if (fuzzy(m.home?.name, teamName)) return m.home.id;
    if (fuzzy(m.away?.name, teamName)) return m.away.id;
  }
  return null;
}

const _euClubFixturesCache = {}; // `${leagueId}` → { data, ts }
async function fetchApiFootballUpcomingFixtures(leagueId, season, windowMs) {
  const cacheKey = `${leagueId}_${season}`;
  const cached = _euClubFixturesCache[cacheKey];
  // 30min au lieu de 15min (25 août 2026) — plus court que le cycle bg-alerts (20min), donc quasi
  // toujours périmé au cycle suivant malgré une liste de matchs qui bouge rarement (report de match
  // = seul cas réel de changement). Aligné sur _euClubMatchesCache (même donnée, déjà à 30min).
  if (cached && Date.now() - cached.ts < 30 * 60_000) return cached.data;
  if (!process.env.FOOTBALL_API_KEY) return [];
  try {
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures?league=${leagueId}&season=${season}&status=NS`);
    const now = Date.now();
    const data = (j.response || []).filter(fx => {
      const t = new Date(fx.fixture.date).getTime();
      return t > now && (t - now) <= windowMs;
    });
    _bgLog.push(`fetchApiFootballUpcomingFixtures(${leagueId},${season}): ${j.response?.length ?? 'null'} bruts, ${data.length} dans la fenêtre`);
    _euClubFixturesCache[cacheKey] = { data, ts: Date.now() };
    return data;
  } catch (e) { _bgLog.push(`fetchApiFootballUpcomingFixtures(${leagueId},${season}) error: ${e.message}`); return []; }
}

// Interrupteur Brasileirão (17 juillet 2026, activé le 19 juillet 2026 après revue utilisateur).
// Le fetch fixtures/cotes tourne déjà (isolé, zéro impact sur les 5 grands championnats).
const BRESIL_ALERTS_ENABLED = true;
const CDM_AVG_GOALS = 1.30;
// Fallback si aucune stat CDM disponible (avgGF/avgGA normalement calculés dynamiquement
// sur le pool d'équipes programmées, cf section 4d) — anciennes moyennes observées (~17 sélections).
const CDM_AVG_GF = 2.15;
const CDM_AVG_GA = 0.78;
let _cdmPoolAvg = { avgGF: CDM_AVG_GF, avgGA: CDM_AVG_GA }; // mis à jour par generateBackgroundAlerts

// avgGF/avgGA figés par match dès sa 1ère génération (au lieu d'être recalculés à chaque
// cycle de 20min sur le pool courant) — évite qu'un match déjà suivi voie sa probabilité
// (BTTS/Total/Résultat) dériver fortement sans qu'aucune donnée du match lui-même ait changé
// (cf. cas Mexique-Corée du Sud BTTS 76%→18% en quelques heures, 19 juin 2026).
const CDM_FIXTURE_POOLAVG_FILE = join(CACHE_DIR, 'cdm_fixture_poolavg.json');
let _cdmFixturePoolAvg = {};
try { if (existsSync(CDM_FIXTURE_POOLAVG_FILE)) _cdmFixturePoolAvg = JSON.parse(readFileSync(CDM_FIXTURE_POOLAVG_FILE, 'utf8')); } catch {}
const _saveCdmFixturePoolAvg = () => { try { writeFileSync(CDM_FIXTURE_POOLAVG_FILE, JSON.stringify(_cdmFixturePoolAvg), 'utf8'); } catch {} };
function freezeCdmPoolAvg(fixtureId, avgGF, avgGA) {
  const existing = _cdmFixturePoolAvg[fixtureId];
  if (existing) return existing;
  const frozen = { avgGF, avgGA, frozenAt: Date.now() };
  _cdmFixturePoolAvg[fixtureId] = frozen;
  _saveCdmFixturePoolAvg();
  return frozen;
}
const FB_BTTS_ALERT_PROB   = 0.70;
// Redescendu à 65% le 27 août 2026 (même soirée) — le relevé à 80% ci-dessus reposait sur un
// calcul sans filtre de cote réellement pariable : en exigeant la vraie cote minimum du marché
// (FB_OU_ALERT_MIN_ODDS_TOTAL, 1.20 depuis ce fix), 80% ne produisait tout simplement JAMAIS
// d'alerte réelle sur tout l'historique (28 juil-26 août), et 70%+ donnait un taux de réussite
// catastrophique (16,7% sur 6 cas). La vraie zone qui tient — y compris testée sur données
// jamais vues (validation temporelle, pas juste l'historique complet) — est ≥65% : 60,3% de
// réussite (n=58), et sur un split chronologique 51,7% (1ère moitié) → 69,0% (2ème moitié,
// jamais vue) — ne s'effondre pas, contrairement à 80% qui n'a jamais pu être testé faute de
// candidats. Classé "en observation" (moins de certitude que Résultat WNBA), pas "confirmé".
const FB_OU_ALERT_PROB     = 0.65;
// Baissé de 1.60 (partagé avec BTTS, resté à 1.60, aucune preuve pour lui) — 1.20 essayé d'abord
// (58 candidats, 60,3% de réussite) mais ROI réel négatif (-15,6%, cotes trop courtes pour
// compenser les pertes). 1.30 retenu à la place : quasi le même taux de réussite (60,0%, n=25)
// mais ROI bien meilleur (-2,8%) — vrai compromis, pas juste une préférence de confort sur la cote.
const FB_OU_ALERT_MIN_ODDS_TOTAL = 1.30;
const FB_RESULT_ALERT_PROB = 0.70; // par issue (home/draw/away) — chaque issue est un pari oui/non indépendant
const FB_RESULT_MAX_PROB   = 0.80; // plafond de confiance 1X2 — le modèle Poisson sur stats qualifs/amicaux surestime les favoris
const FB_BTTS_OU_MIN_ODDS  = 1.60; // cote mini BTTS/O-U (unibet/betclic — winamax exclu)
const FB_RESULT_MIN_ODDS   = 1.50; // cote mini Résultat 1X2 (unibet/betclic — winamax exclu)
const FB_DC_BTTS_ALERT_PROB = 0.50; // proba mini DC & BTTS (combiné — plafond ~50% pour les matchs les plus forts)
const FB_DC_OU_ALERT_PROB   = 0.55; // proba mini DC & Over 1.5
const FB_DC_MIN_ODDS        = 1.45; // cote mini DC combinés

// ── football-data.org (TEST) ──────────────────────────────────────────────────
const FD_KEY  = process.env.FD_API_KEY;
const FD_BASE = 'https://api.football-data.org/v4';
const FD_LEAGUES = [
  { code: 'FL1', key: 'ligue1' },
  { code: 'PL',  key: 'pl'     },
  { code: 'PD',  key: 'laliga' },
  { code: 'BL1', key: 'bundes' },
  { code: 'SA',  key: 'seriea' },
];

async function fdGet(path) {
  const resp = await fetch(`${FD_BASE}${path}`, { headers: { 'X-Auth-Token': FD_KEY } });
  if (!resp.ok) throw new Error(`football-data.org ${resp.status}: ${path}`);
  _captureFdQuota(resp);
  return resp.json();
}

// Cache persisté sur disque : survit aux redémarrages (--watch), même pattern
// que la CDM — un 429 transitoire ne vide plus l'affichage des 5 championnats.
let _fdCache = null;
let _fdCacheTs = 0;
let _fdErrorUntil = 0;
try {
  if (existsSync(FD_MATCHES_CACHE_FILE)) {
    const parsed = JSON.parse(readFileSync(FD_MATCHES_CACHE_FILE, 'utf8'));
    if (parsed?.matches) { _fdCache = { matches: parsed.matches, count: parsed.matches.length }; _fdCacheTs = parsed.ts || 0; }
  }
} catch {}

// Classement complet (toutes les équipes, pas seulement celles des 5 prochaines fixtures) et
// calendrier restant complet par ligue — pour les outrights (28 juillet 2026). Réutilise
// `standingsRes`/`matchesRes` déjà fetchés dans /api/fd/matches ci-dessous, aucun appel FD
// supplémentaire (quota FD très serré, 10 req/min). Clé = league.key (ligue1/pl/laliga/bundes/seriea).
let _fdFullStandingsCache = {};
try { if (existsSync(FD_FULL_STANDINGS_CACHE_FILE)) _fdFullStandingsCache = JSON.parse(readFileSync(FD_FULL_STANDINGS_CACHE_FILE, 'utf8')); } catch {}
const _saveFdFullStandings = () => { try { writeFileSync(FD_FULL_STANDINGS_CACHE_FILE, JSON.stringify(_fdFullStandingsCache), 'utf8'); } catch {} };

let _fdRemainingFixturesCache = {};
try { if (existsSync(FD_REMAINING_FIXTURES_CACHE_FILE)) _fdRemainingFixturesCache = JSON.parse(readFileSync(FD_REMAINING_FIXTURES_CACHE_FILE, 'utf8')); } catch {}
const _saveFdRemainingFixtures = () => { try { writeFileSync(FD_REMAINING_FIXTURES_CACHE_FILE, JSON.stringify(_fdRemainingFixturesCache), 'utf8'); } catch {} };

// Détection classement périmé (28 juillet 2026, découvert en construisant les outrights) —
// football-data.org crée la nouvelle saison (season.currentMatchday=1, season.winner=null) AVANT
// que son tableau `standings` soit réinitialisé : PL/La Liga/Bundesliga renvoyaient encore la
// grille FINALE de la saison précédente (38/34 matchs joués) sous une saison techniquement déjà
// "nouvelle" — a produit des alertes outrights sur Arsenal/Real Madrid/Man City comme si la saison
// 2026/27 était presque jouée. Ligue 1/Serie A n'avaient pas ce problème (déjà à 0 joué). Signal
// fiable : si l'équipe en tête a joué plus de matchs que `currentMatchday` ne le permettrait, la
// table est celle d'une saison différente — à ignorer entièrement tant que FD ne l'a pas corrigée.
let _fdSeasonInfo = {}; // league.key -> { currentMatchday, winner, stale }
try { if (existsSync(FD_SEASON_INFO_CACHE_FILE)) _fdSeasonInfo = JSON.parse(readFileSync(FD_SEASON_INFO_CACHE_FILE, 'utf8')); } catch {}
const _saveFdSeasonInfo = () => { try { writeFileSync(FD_SEASON_INFO_CACHE_FILE, JSON.stringify(_fdSeasonInfo), 'utf8'); } catch {} };
function _isFdStandingsStale(currentMatchday, table) {
  if (!table?.length) return false;
  return table[0].playedGames > (currentMatchday || 0) + 1;
}

app.get('/api/fd/matches', async (req, res) => {
  if (!FD_KEY) return res.status(503).json({ error: 'FD_API_KEY not configured' });
  if (_fdCache && Date.now() - _fdCacheTs < 30 * 60 * 1000) return res.json(_fdCache);
  // FD limite à 10 req/min — si une tentative récente a échoué (429), on sert le cache
  // périmé (ou une liste vide) au lieu de re-tenter immédiatement et d'aggraver le 429
  if (Date.now() < _fdErrorUntil) return res.json(_fdCache || { matches: [], count: 0 });

  try {
    const allMatches = [];
    for (const league of FD_LEAGUES) {
      // Rate limit 10 req/min : les 2 requêtes par ligue (matches+standings) étaient lancées
      // en parallèle, avec seulement 200ms entre ligues — les 10 requêtes partaient en moins
      // d'1 seconde et saturaient tout le quota de la minute d'un coup. N'importe quel autre
      // appel FD (CDM, teamstats) tombant dans cette même minute se prenait un 429. Espacement
      // de chaque requête individuellement (pas juste entre ligues) pour laisser de la marge.
      // Fix 23 août 2026 — status=SCHEDULED seul excluait aussi les matchs EN DIRECT (IN_PLAY/
      // PAUSED côté football-data.org), pas seulement les terminés (l'intention d'origine).
      // MatchDetailPage.jsx dépend entièrement de cette liste pour retrouver une fiche par id —
      // un match qui passait en direct disparaissait donc de la liste et affichait "Match
      // introuvable" pile pendant qu'on voulait le suivre (cas réel : Atletico Madrid-Villarreal).
      // Vérifié en direct : FD accepte les statuts en liste séparée par virgules dans un seul
      // appel, aucun coût de quota supplémentaire.
      // Fix 29 août 2026 — même souci pour un match TERMINÉ (demande explicite : "je veux brancher
      // pour que tout ce qu'on avait en pré-match s'affiche même sur le match terminé"). FINISHED
      // ajouté au filtre + fenêtre dateFrom/dateTo bornée (même convention que _getFdLeaguesResults
      // : -2j) pour ne récupérer que les matchs RÉCEMMENT terminés, pas tout l'historique de la
      // saison (qui écraserait le slice(0,5) "prochains matchs" avec de vieux matchs joués il y a
      // des mois, en plus d'un payload inutilement lourd). Coût quota inchangé (toujours 1 requête).
      const dateFrom = new Date(Date.now() - 2 * 86400_000).toISOString().slice(0, 10);
      const dateTo   = new Date(Date.now() + 45 * 86400_000).toISOString().slice(0, 10);
      const matchesRes = await fdGet(`/competitions/${league.code}/matches?status=SCHEDULED,IN_PLAY,PAUSED,FINISHED&dateFrom=${dateFrom}&dateTo=${dateTo}`);
      await new Promise(r => setTimeout(r, 600));
      const standingsRes = await fdGet(`/competitions/${league.code}/standings`);
      await new Promise(r => setTimeout(r, 600));

      // Classement : teamId → stats
      const table = standingsRes.standings?.find(s => s.type === 'TOTAL')?.table || [];
      const statsMap = {};
      for (const s of table) {
        statsMap[s.team.id] = {
          position:     s.position,
          points:       s.points,
          played:       s.playedGames,
          wins:         s.won,
          draws:        s.draw,
          losses:       s.lost,
          goalsFor:     s.goalsFor,
          goalsAgainst: s.goalsAgainst,
          form: (s.form || '').split('').filter(c => 'WDL'.includes(c)).slice(-5),
        };
      }

      // Classement complet + calendrier restant complet pour les outrights — table/matchesRes
      // couvrent déjà TOUTES les équipes/tout le reste de la saison, statsMap/upcoming ci-dessous
      // ne fait que les tronquer pour l'usage fixtures existant. Aucun appel FD en plus.
      _fdSeasonInfo[league.key] = {
        currentMatchday: standingsRes.season?.currentMatchday ?? null,
        winner: standingsRes.season?.winner ?? null,
        stale: _isFdStandingsStale(standingsRes.season?.currentMatchday, table),
      };
      _fdFullStandingsCache[league.key] = table.map(s => ({
        teamId: s.team.id, teamName: s.team.name,
        position: s.position, points: s.points, played: s.playedGames,
        wins: s.won, draws: s.draw, losses: s.lost,
        goalsFor: s.goalsFor, goalsAgainst: s.goalsAgainst,
        form: (s.form || '').split('').filter(c => 'WDL'.includes(c)).slice(-5),
      }));
      // FINISHED exclu de ce cache (29 août 2026) — matchesRes contient désormais aussi les matchs
      // récemment terminés (cf. fetch ci-dessus), mais le "calendrier restant" pour les outrights ne
      // doit jamais inclure un match déjà joué.
      const notFinishedFd = (matchesRes.matches || []).filter(m => m.status !== 'FINISHED' && m.status !== 'AWARDED');
      _fdRemainingFixturesCache[league.key] = notFinishedFd.map(m => ({
        id: String(m.id), date: m.utcDate, matchday: m.matchday,
        homeTeamId: m.homeTeam.id, homeTeamName: m.homeTeam.name,
        awayTeamId: m.awayTeam.id, awayTeamName: m.awayTeam.name,
        // Ajouté 27 août 2026 — nécessaire pour exclure les matchs déjà en direct du moteur
        // d'alertes (cf. filtre dans la boucle fbFixtures). Champ additif, n'affecte aucun
        // consommateur existant de ce cache (outrights) qui ne lit pas cette clé.
        status: m.status,
      }));
      // Sauvegarde par ligue, pas seulement à la fin des 5 (28 juillet 2026) — la boucle FD peut
      // s'interrompre en cours de route (429, 10 req/min très serré) ; sans ça, un cycle interrompu
      // perdait purement et simplement les ligues déjà traitées (jamais persistées), y compris
      // _fdSeasonInfo, pourtant critique pour la détection de classement périmé des outrights.
      _saveFdFullStandings();
      _saveFdRemainingFixtures();
      _saveFdSeasonInfo();

      // 5 prochains matchs + matchs récemment terminés (29 août 2026, demande explicite — "je veux
      // brancher pour que tout ce qu'on avait en pré-match s'affiche même sur le match terminé").
      // "5 prochains" reste calculé sur notFinishedFd uniquement (comportement inchangé — le widget
      // dédié "5 prochains matchs" ne doit jamais se faire polluer par un match déjà joué) ; les
      // matchs FINISHED des dernières 48h (même fenêtre que la CDM, /api/fd/worldcup) sont ajoutés
      // À CÔTÉ, pas à la place — ils restent cliquables sans jamais pousser un vrai match à venir
      // hors du top 5.
      const FD_STATUS_MAP_MATCHES = {
        SCHEDULED: 'STATUS_SCHEDULED', TIMED: 'STATUS_SCHEDULED',
        IN_PLAY: 'STATUS_IN_PROGRESS', PAUSED: 'STATUS_IN_PROGRESS',
        FINISHED: 'STATUS_FINAL', AWARDED: 'STATUS_FINAL',
      };
      const FD_KEEP_FINISHED_MS = 48 * 3600_000;
      const recentFinishedFd = (matchesRes.matches || []).filter(m =>
        (m.status === 'FINISHED' || m.status === 'AWARDED') &&
        (Date.now() - new Date(m.utcDate).getTime()) < FD_KEEP_FINISHED_MS
      );
      const upcoming = [...recentFinishedFd, ...notFinishedFd.slice(0, 5)];
      for (const m of upcoming) {
        const hId = m.homeTeam.id;
        const aId = m.awayTeam.id;
        allMatches.push({
          id:      String(m.id),
          league:  league.key,
          round:   m.matchday ? `Journée ${m.matchday}` : '',
          date:    m.utcDate,
          status:  FD_STATUS_MAP_MATCHES[m.status] || 'STATUS_SCHEDULED',
          venue:   null,
          weather: null,
          isLive:  true,
          home: { id: hId, name: m.homeTeam.name, short: m.homeTeam.tla || abbrev(m.homeTeam.name), logoId: m.homeTeam.crest, score: m.score?.fullTime?.home ?? null, upcoming: [], ...(statsMap[hId] || {}) },
          away: { id: aId, name: m.awayTeam.name, short: m.awayTeam.tla || abbrev(m.awayTeam.name), logoId: m.awayTeam.crest, score: m.score?.fullTime?.away ?? null, upcoming: [], ...(statsMap[aId] || {}) },
          h2h:     [],
          markets: {},
        });
      }
    }

    allMatches.sort((a, b) => new Date(a.date) - new Date(b.date));
    const result = { matches: allMatches, count: allMatches.length };
    _fdCache = result;
    _fdCacheTs = Date.now();
    try { writeFileSync(FD_MATCHES_CACHE_FILE, JSON.stringify({ matches: allMatches, ts: _fdCacheTs }), 'utf8'); } catch {}
    _saveFdFullStandings();
    _saveFdRemainingFixtures();
    _saveFdSeasonInfo();
    res.json(result);
  } catch (err) {
    console.error('football-data.org error:', err.message);
    _fdErrorUntil = Date.now() + 60 * 1000;
    res.json(_fdCache || { matches: [], count: 0 });
  }
});

// ── Coupe du Monde (football-data.org) ───────────────────────────────────────
// Cache persisté sur disque : survit aux redémarrages (--watch) pour éviter qu'un
// rate-limit FD (10 req/min, partagé avec /api/fd/matches) ne vide l'affichage CDM.
let _cdmCache = null, _cdmCacheTs = 0, _cdmErrorUntil = 0;
try {
  if (existsSync(WORLDCUP_CACHE_FILE)) {
    const parsed = JSON.parse(readFileSync(WORLDCUP_CACHE_FILE, 'utf8'));
    if (parsed?.games) { _cdmCache = { games: parsed.games }; _cdmCacheTs = parsed.ts || 0; }
  }
} catch {}
app.get('/api/fd/worldcup', async (req, res) => {
  if (!FD_KEY) return res.status(503).json({ error: 'FD_API_KEY not configured' });
  // Cache plus court (1min) si un match est en cours — pour suivre les buts en quasi
  // temps réel ; sinon 5min (réduit le délai de détection du passage en live, quota FD
  // 10 req/min largement assez large pour ça).
  const hasLive = _cdmCache?.games?.some(g => g.status === 'STATUS_IN_PROGRESS');
  const ttl = hasLive ? 60 * 1000 : 5 * 60 * 1000;
  if (_cdmCache && Date.now() - _cdmCacheTs < ttl) return res.json(_cdmCache);
  if (Date.now() < _cdmErrorUntil) return res.json(_cdmCache || { games: [] });
  try {
    const r = await fetch('https://api.football-data.org/v4/competitions/2000/matches?limit=30', { headers: { 'X-Auth-Token': FD_KEY } });
    if (!r.ok) throw new Error(`FD ${r.status}`);
    const d = await r.json();
    const FD_STATUS_MAP = {
      SCHEDULED: 'STATUS_SCHEDULED', TIMED: 'STATUS_SCHEDULED',
      // "LIVE" observé en direct sur l'API (23 juin 2026, Angleterre-Ghana) en plus de IN_PLAY/PAUSED —
      // pas documenté dans l'enum officiel FD mais bien renvoyé, sans ce mapping le match disparaît
      // du résultat (filtré comme POSTPONED/CANCELLED) et le cycle de refresh rapide live ne s'active jamais.
      IN_PLAY: 'STATUS_IN_PROGRESS', PAUSED: 'STATUS_IN_PROGRESS', LIVE: 'STATUS_IN_PROGRESS',
      EXTRA_TIME: 'STATUS_IN_PROGRESS', PENALTY_SHOOTOUT: 'STATUS_IN_PROGRESS',
      FINISHED: 'STATUS_FINAL', AWARDED: 'STATUS_FINAL',
    };
    const now = Date.now();
    const KEEP_MS = 48 * 3600_000;
    const games = (d.matches || [])
      .filter(m => {
        const mapped = FD_STATUS_MAP[m.status];
        if (!mapped) return false; // POSTPONED, CANCELLED, SUSPENDED
        if (mapped === 'STATUS_FINAL') return (now - new Date(m.utcDate).getTime()) < KEEP_MS;
        return true;
      })
      .slice(0, 20).map(m => {
        // fullTime inclut les prolongations pour les matchs à élimination directe (score.extraTime
        // renvoie les buts marqués en prolongation seulement). La plupart des marchés (DC, BTTS, O/U,
        // Résultat 1X2) se règlent sur le temps réglementaire (90min) sauf mention contraire du
        // bookmaker — scoreReg = fullTime - extraTime, utilisé pour le settlement. `score` reste le
        // score final réel (avec prolongation) pour l'affichage.
        const ftHome = m.score?.fullTime?.home ?? null;
        const ftAway = m.score?.fullTime?.away ?? null;
        const etHome = m.score?.extraTime?.home ?? 0;
        const etAway = m.score?.extraTime?.away ?? 0;
        return {
          id:     m.id,
          date:   m.utcDate,
          status: FD_STATUS_MAP[m.status],
          round:  m.stage?.replace(/_/g,' ') || m.matchday ? `J${m.matchday}` : '',
          home:   { name: m.homeTeam?.name, short: m.homeTeam?.shortName, logo: m.homeTeam?.crest, score: ftHome, scoreReg: ftHome != null ? ftHome - etHome : null },
          away:   { name: m.awayTeam?.name, short: m.awayTeam?.shortName, logo: m.awayTeam?.crest, score: ftAway, scoreReg: ftAway != null ? ftAway - etAway : null },
        };
      });
    _cdmCache = { games }; _cdmCacheTs = Date.now();
    try { writeFileSync(WORLDCUP_CACHE_FILE, JSON.stringify({ games, ts: _cdmCacheTs }), 'utf8'); } catch {}
    res.json(_cdmCache);
  } catch (err) {
    console.error('football-data.org worldcup error:', err.message);
    _cdmErrorUntil = Date.now() + 60 * 1000;
    res.json(_cdmCache || { games: [] });
  }
});

// ── Brasileirão (football-data.org, BSA) — 17 juillet 2026 ────────────────────
// Complètement isolé de _fdCache/FD_LEAGUES (les 5 grands championnats) : cache, TTL et
// gestion d'erreur séparés, pour qu'un souci sur cette route ne puisse jamais dégrader la
// fiabilité des 5 ligues existantes. Même principe déjà validé par /api/fd/worldcup (CDM)
// ci-dessus, qui partage aussi le quota FD (10 req/min) sans jamais avoir posé de problème.
let _bresilCache = null, _bresilCacheTs = 0, _bresilErrorUntil = 0;
try {
  if (existsSync(BRESIL_CACHE_FILE)) {
    const parsed = JSON.parse(readFileSync(BRESIL_CACHE_FILE, 'utf8'));
    if (parsed?.matches) { _bresilCache = { matches: parsed.matches, count: parsed.matches.length }; _bresilCacheTs = parsed.ts || 0; }
  }
} catch {}

// Fonction partagée route + generateBackgroundAlerts (section 4d) — un seul endroit qui parle
// réellement à football-data.org pour le Brésil, tout le monde relit le même cache derrière.
// Statuts football-data.org → statuts internes app — même mapping que /api/fd/worldcup (CDM).
const FD_STATUS_MAP_BRESIL = {
  SCHEDULED: 'STATUS_SCHEDULED', TIMED: 'STATUS_SCHEDULED',
  IN_PLAY: 'STATUS_IN_PROGRESS', PAUSED: 'STATUS_IN_PROGRESS', LIVE: 'STATUS_IN_PROGRESS',
  FINISHED: 'STATUS_FINAL', AWARDED: 'STATUS_FINAL',
};

async function _getBresilMatches() {
  if (!FD_KEY) return { matches: [], count: 0 };
  if (_bresilCache && Date.now() - _bresilCacheTs < 30 * 60 * 1000) return _bresilCache;
  if (Date.now() < _bresilErrorUntil) return _bresilCache || { matches: [], count: 0 };
  try {
    // Pas de filtre status : fenêtre de dates couvrant les 2 derniers jours (matchs à régler,
    // scores) jusqu'à 14 jours à venir — même principe que /api/fd/worldcup (CDM), qui garde les
    // matchs terminés 48h avant de les faire disparaître. Sans ça, un match joué disparaissait
    // juste de la liste (filtre SCHEDULED) au lieu de passer en "Terminé" avec le score (18 juillet 2026).
    const dateFrom = new Date(Date.now() - 2 * 86400_000).toISOString().slice(0, 10);
    const dateTo   = new Date(Date.now() + 14 * 86400_000).toISOString().slice(0, 10);
    const matchesRes = await fdGet(`/competitions/BSA/matches?dateFrom=${dateFrom}&dateTo=${dateTo}`);
    await new Promise(r => setTimeout(r, 600));
    const standingsRes = await fdGet('/competitions/BSA/standings');

    const table = standingsRes.standings?.find(s => s.type === 'TOTAL')?.table || [];
    const statsMap = {};
    for (const s of table) {
      statsMap[s.team.id] = {
        position: s.position, points: s.points, played: s.playedGames,
        wins: s.won, draws: s.draw, losses: s.lost,
        goalsFor: s.goalsFor, goalsAgainst: s.goalsAgainst,
        form: (s.form || '').split('').filter(c => 'WDL'.includes(c)).slice(-5),
      };
    }

    // Fix 27 août 2026 — football-data.org renvoie parfois, sur cette compétition précise, un
    // champ `status` corrompu contenant la date/heure du match ("2026-08-29 21:30:00Z") au lieu
    // de l'enum attendu (SCHEDULED/FINISHED/...) — bug constaté côté FD lui-même (vérifié via un
    // appel direct hors backend, même résultat), pas une régression de ce code. Conséquence
    // silencieuse : `FD_STATUS_MAP_BRESIL[m.status]` ne matchait jamais rien, donc TOUS les
    // matchs Brésil étaient filtrés → "Aucun match dans les prochaines 30h" affiché en permanence
    // même un jour de plusieurs matchs programmés. Filet de sécurité : si `m.status` ne matche
    // aucune valeur connue, déduire le statut depuis le score (rempli = terminé, sinon programmé)
    // plutôt que de perdre le match entier.
    const inferBresilStatus = m => {
      const mapped = FD_STATUS_MAP_BRESIL[m.status];
      if (mapped) return mapped;
      return (m.score?.fullTime?.home != null && m.score?.fullTime?.away != null) ? 'STATUS_FINAL' : 'STATUS_SCHEDULED';
    };
    const KEEP_MS = 48 * 3600_000;
    const now = Date.now();
    const relevant = (matchesRes.matches || [])
      .filter(m => {
        const status = ['POSTPONED', 'CANCELLED', 'SUSPENDED'].includes(m.status) ? null : inferBresilStatus(m);
        if (!status) return false;
        if (status === 'STATUS_FINAL') return (now - new Date(m.utcDate).getTime()) < KEEP_MS;
        return true;
      })
      .slice(0, 15);
    const allMatches = relevant.map(m => {
      const hId = m.homeTeam.id, aId = m.awayTeam.id;
      const status = inferBresilStatus(m);
      const ftHome = m.score?.fullTime?.home ?? null;
      const ftAway = m.score?.fullTime?.away ?? null;
      return {
        id: String(m.id), league: 'bresil', round: m.matchday ? `Journée ${m.matchday}` : '',
        date: m.utcDate, venue: null, weather: null, isLive: true, status,
        home: { id: hId, name: m.homeTeam.name, short: m.homeTeam.tla || abbrev(m.homeTeam.name), logoId: m.homeTeam.crest, score: ftHome, upcoming: [], ...(statsMap[hId] || {}) },
        away: { id: aId, name: m.awayTeam.name, short: m.awayTeam.tla || abbrev(m.awayTeam.name), logoId: m.awayTeam.crest, score: ftAway, upcoming: [], ...(statsMap[aId] || {}) },
        h2h: [], markets: {},
      };
    });

    const result = { matches: allMatches, count: allMatches.length };
    _bresilCache = result; _bresilCacheTs = Date.now();
    try { writeFileSync(BRESIL_CACHE_FILE, JSON.stringify({ matches: allMatches, ts: _bresilCacheTs }), 'utf8'); } catch {}
    return result;
  } catch (err) {
    console.error('football-data.org bresil error:', err.message);
    _bresilErrorUntil = Date.now() + 60 * 1000;
    return _bresilCache || { matches: [], count: 0 };
  }
}

app.get('/api/fd/bresil', async (req, res) => {
  if (!FD_KEY) return res.status(503).json({ error: 'FD_API_KEY not configured' });
  res.json(await _getBresilMatches());
});

// Ligue 1 / PL / La Liga / Bundesliga / Serie A — scores finaux pour le règlement frontend
// (24 juillet 2026). _getFdLeaguesResults() existait déjà côté backend (utilisée par runAutoSettle()
// et _resolveFootballNearMiss() depuis le 21 juillet) mais n'était jamais exposée en HTTP — le
// règlement de resolveCompletedFootballAlerts() (syncAlerts.js, ce qui détermine gagné/perdu affiché
// à l'utilisateur) restait donc bloqué sur ces 5 championnats faute de source. Même forme que
// /api/fd/bresil ci-dessus ({matches:[{id,league,status,home:{score},away:{score}}]}).
app.get('/api/fd/results', async (req, res) => {
  if (!FD_KEY) return res.status(503).json({ error: 'FD_API_KEY not configured' });
  res.json(await _getFdLeaguesResults());
});

// ── Europa League / Conference League — liste des matchs pour la Carte du Monde (23 juillet 2026)
// Même format que _getBresilMatches ci-dessus (id/date/status/round/home/away), source api-football
// au lieu de football-data.org — team logos fournis directement par l'API (fx.teams.home.logo).
// fixtureId préfixé `afel_`/`afcl_` côté frontend, même convention que generateBackgroundAlerts().
const EU_CLUB_STATUS_MAP = {
  NS: 'STATUS_SCHEDULED', TBD: 'STATUS_SCHEDULED', PST: null, CANC: null, ABD: null, SUSP: null, WO: null,
  '1H': 'STATUS_IN_PROGRESS', '2H': 'STATUS_IN_PROGRESS', HT: 'STATUS_IN_PROGRESS', ET: 'STATUS_IN_PROGRESS', P: 'STATUS_IN_PROGRESS', BT: 'STATUS_IN_PROGRESS',
  FT: 'STATUS_FINAL', AET: 'STATUS_FINAL', PEN: 'STATUS_FINAL',
};
let _euClubMatchesCache = {}; // compKey → { data, ts }
async function _getEuClubMatches(compKey) {
  const cached = _euClubMatchesCache[compKey];
  if (cached && Date.now() - cached.ts < 30 * 60_000) return cached.data;
  if (!process.env.FOOTBALL_API_KEY || !EU_CLUB_COMP_IDS[compKey]) return { matches: [], count: 0 };
  try {
    const leagueId = EU_CLUB_COMP_IDS[compKey];
    const season = footballApiSeasonForDate('ligue1', new Date().toISOString());
    const j = await footballApiFetch(`${FOOTBALL_API_BASE}/fixtures?league=${leagueId}&season=${season}`);
    const now = Date.now();
    const KEEP_MS = 48 * 3600_000, WINDOW_MS = 14 * 86400_000;
    const relevant = (j.response || []).filter(fx => {
      const t = new Date(fx.fixture.date).getTime();
      const mapped = EU_CLUB_STATUS_MAP[fx.fixture.status?.short];
      if (!mapped) return false;
      if (mapped === 'STATUS_FINAL') return (now - t) < KEEP_MS;
      return (t - now) < WINDOW_MS;
    });
    const matches = relevant.map(fx => ({
      id: String(fx.fixture.id), league: compKey, round: fx.league.round || '',
      date: fx.fixture.date, status: EU_CLUB_STATUS_MAP[fx.fixture.status?.short] || 'STATUS_SCHEDULED',
      home: { id: fx.teams.home.id, name: fx.teams.home.name, short: abbrev(fx.teams.home.name), logoId: fx.teams.home.logo, score: fx.goals?.home ?? null },
      away: { id: fx.teams.away.id, name: fx.teams.away.name, short: abbrev(fx.teams.away.name), logoId: fx.teams.away.logo, score: fx.goals?.away ?? null },
    }));
    matches.sort((a, b) => new Date(a.date) - new Date(b.date));
    const result = { matches, count: matches.length };
    _euClubMatchesCache[compKey] = { data: result, ts: Date.now() };
    return result;
  } catch (err) {
    console.error(`api-football ${compKey} matches error:`, err.message);
    return _euClubMatchesCache[compKey]?.data || { matches: [], count: 0 };
  }
}
app.get('/api/football/eucup/:comp/matches', async (req, res) => {
  const comp = req.params.comp;
  if (!EU_CLUB_COMP_IDS[comp]) return res.status(404).json({ error: 'unknown competition' });
  res.json(await _getEuClubMatches(comp));
});

// ── Résultats des 5 grands championnats — pour le règlement automatique uniquement (21 juillet
// 2026). /api/fd/matches interroge FD avec ?status=SCHEDULED (jamais de score, jamais de match
// terminé) — les alertes BTTS/Total/Résultat foot sur ces 5 ligues ne se réglaient donc JAMAIS,
// ni côté serveur ni côté navigateur (seule la Coupe du Monde, via /api/fd/worldcup, avait une
// source de score). Fonction et cache complètement séparés de _fdCache/FD_MATCHES_CACHE_FILE —
// même principe d'isolation déjà validé pour le Brésil ci-dessus, zéro risque sur l'affichage
// existant des 5 championnats (fixtures à venir + classement).
let _fdResultsCache = null, _fdResultsCacheTs = 0, _fdResultsErrorUntil = 0;
try {
  if (existsSync(FD_RESULTS_CACHE_FILE)) {
    const parsed = JSON.parse(readFileSync(FD_RESULTS_CACHE_FILE, 'utf8'));
    if (parsed?.matches) { _fdResultsCache = { matches: parsed.matches }; _fdResultsCacheTs = parsed.ts || 0; }
  }
} catch {}
const FD_STATUS_MAP_RESULTS = {
  IN_PLAY: 'STATUS_IN_PROGRESS', PAUSED: 'STATUS_IN_PROGRESS', LIVE: 'STATUS_IN_PROGRESS',
  FINISHED: 'STATUS_FINAL', AWARDED: 'STATUS_FINAL',
};
// football-data.org laisse parfois un match "IN_PLAY" en amont bien après la fin réelle (constaté
// en direct : Deportivo La Coruña-Valencia toujours IN_PLAY 5h30 après le coup d'envoi, y compris
// sur un fetch tout juste rafraîchi — pas un souci de cache côté nous). Un vrai match ne dépasse
// jamais ~2h30 (90min + mi-temps + prolongations/tirs au but éventuels) ; au-delà, on force FINISHED
// pour ne pas laisser WorldMapPage afficher "EN COURS" indéfiniment sur un match déjà terminé.
const FD_MAX_LIVE_MATCH_MS = 3 * 3600_000;
async function _getFdLeaguesResults() {
  if (!FD_KEY) return { matches: [] };
  if (_fdResultsCache && Date.now() - _fdResultsCacheTs < 30 * 60 * 1000) return _fdResultsCache;
  if (Date.now() < _fdResultsErrorUntil) return _fdResultsCache || { matches: [] };
  try {
    const dateFrom = new Date(Date.now() - 2 * 86400_000).toISOString().slice(0, 10);
    const dateTo   = new Date(Date.now() + 1 * 86400_000).toISOString().slice(0, 10);
    const allMatches = [];
    for (const league of FD_LEAGUES) {
      const matchesRes = await fdGet(`/competitions/${league.code}/matches?dateFrom=${dateFrom}&dateTo=${dateTo}`);
      await new Promise(r => setTimeout(r, 600));
      for (const m of (matchesRes.matches || [])) {
        let mapped = FD_STATUS_MAP_RESULTS[m.status];
        if (!mapped) continue; // POSTPONED, CANCELLED, SUSPENDED, SCHEDULED (pas encore joué, rien à régler)
        if (mapped === 'STATUS_IN_PROGRESS' && Date.now() - new Date(m.utcDate).getTime() > FD_MAX_LIVE_MATCH_MS) {
          mapped = 'STATUS_FINAL';
        }
        allMatches.push({
          id: String(m.id), league: league.key, status: mapped, date: m.utcDate,
          home: { name: m.homeTeam?.name, short: m.homeTeam?.shortName, logo: m.homeTeam?.crest, score: m.score?.fullTime?.home ?? null },
          away: { name: m.awayTeam?.name, short: m.awayTeam?.shortName, logo: m.awayTeam?.crest, score: m.score?.fullTime?.away ?? null },
        });
      }
    }
    // date/home.name/home.logo/away.name/away.logo ajoutés le 16 août 2026 — déjà présents dans la
    // réponse brute FD (m.utcDate/m.homeTeam/m.awayTeam), juste jamais mappés puisque le seul
    // consommateur jusqu'ici (resolveCompletedFootballAlerts/runAutoSettle) n'a besoin que du score.
    // Permet à WorldMapPage.jsx d'afficher enfin les matchs terminés des 5 grands championnats dans
    // l'onglet "Terminés" (jusqu'ici vide, /api/fd/matches ne renvoie que les matchs SCHEDULED).
    const result = { matches: allMatches };
    _fdResultsCache = result; _fdResultsCacheTs = Date.now();
    try { writeFileSync(FD_RESULTS_CACHE_FILE, JSON.stringify({ matches: allMatches, ts: _fdResultsCacheTs }), 'utf8'); } catch {}
    return result;
  } catch (err) {
    console.error('football-data.org results (5 leagues) error:', err.message);
    _fdResultsErrorUntil = Date.now() + 60 * 1000;
    return _fdResultsCache || { matches: [] };
  }
}

// Récupère un match CDM précis par ID, sans la fenêtre de 48h de /api/fd/worldcup — filet de
// rattrapage pour resolveCompletedFootballAlerts (syncAlerts.js) quand une alerte accepted n'a
// jamais pu être réglée dans les 48h (onglet fermé, panne temporaire...) : le match sort alors du
// cache glissant et ne serait plus jamais trouvable, laissant le pari bloqué sur "accepted" pour
// toujours (bug constaté le 7 juillet 2026, alerte DC Suisse-Algérie du 3 juillet jamais réglée).
app.get('/api/fd/match/:id', async (req, res) => {
  if (!FD_KEY) return res.status(503).json({ error: 'FD_API_KEY not configured' });
  try {
    const r = await fetch(`https://api.football-data.org/v4/matches/${req.params.id}`, { headers: { 'X-Auth-Token': FD_KEY } });
    if (!r.ok) throw new Error(`FD ${r.status}`);
    const m = await r.json();
    if (!m?.id) return res.status(404).json({ error: 'not found' });
    const FD_STATUS_MAP = {
      SCHEDULED: 'STATUS_SCHEDULED', TIMED: 'STATUS_SCHEDULED',
      IN_PLAY: 'STATUS_IN_PROGRESS', PAUSED: 'STATUS_IN_PROGRESS', LIVE: 'STATUS_IN_PROGRESS',
      EXTRA_TIME: 'STATUS_IN_PROGRESS', PENALTY_SHOOTOUT: 'STATUS_IN_PROGRESS',
      FINISHED: 'STATUS_FINAL', AWARDED: 'STATUS_FINAL',
    };
    const ftHome = m.score?.fullTime?.home ?? null;
    const ftAway = m.score?.fullTime?.away ?? null;
    const etHome = m.score?.extraTime?.home ?? 0;
    const etAway = m.score?.extraTime?.away ?? 0;
    res.json({
      id: m.id,
      date: m.utcDate,
      status: FD_STATUS_MAP[m.status] || 'STATUS_SCHEDULED',
      round: m.stage?.replace(/_/g, ' ') || (m.matchday ? `J${m.matchday}` : ''),
      home: { name: m.homeTeam?.name, short: m.homeTeam?.shortName, logo: m.homeTeam?.crest, score: ftHome, scoreReg: ftHome != null ? ftHome - etHome : null },
      away: { name: m.awayTeam?.name, short: m.awayTeam?.shortName, logo: m.awayTeam?.crest, score: ftAway, scoreReg: ftAway != null ? ftAway - etAway : null },
    });
  } catch (err) {
    console.error('football-data.org single match error:', err.message);
    res.status(502).json({ error: err.message });
  }
});

app.use(cors({ origin: ['http://localhost:5173', 'http://localhost:4173'] }));
app.use(express.json({ limit: '10mb' }));

// ── Helpers ──────────────────────────────────────────────────────────────────

function abbrev(name) {
  const parts = name.replace(/[^a-zA-Z\s]/g, '').trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 3).toUpperCase();
  return parts.map(w => w[0]).join('').toUpperCase().slice(0, 4);
}

function removeVig(odds, type) {
  if (type === 'h2h') {
    const s = 1 / odds.home + 1 / odds.draw + 1 / odds.away;
    return { home: (1 / odds.home) / s, draw: (1 / odds.draw) / s, away: (1 / odds.away) / s };
  }
  if (type === 'btts') {
    const s = 1 / odds.yes + 1 / odds.no;
    return { yes: (1 / odds.yes) / s, no: (1 / odds.no) / s };
  }
  return null;
}

// Retrait de marge générique pour un marché à N issues (28 juillet 2026, outrights — un
// championnat a 15-20 équipes, pas 2-3 comme h2h/btts). `teamsOdds` : [{ name, odds }, ...].
// Retourne le même tableau avec un champ `fairProb` ajouté (les probabilités normalisées somment à 1).
function removeVigOutright(teamsOdds) {
  const s = teamsOdds.reduce((sum, t) => sum + 1 / t.odds, 0);
  return teamsOdds.map(t => ({ ...t, fairProb: (1 / t.odds) / s }));
}

function normalizeBookmakerKey(key) {
  const MAP = { betfair_ex_eu: 'betfair', betfair_ex_uk: 'betfair', unibet_eu: 'unibet', unibet_fr: 'unibet', unibet: 'unibet', betclic: 'betclic', winamax_fr: 'winamax', winamax: 'winamax', pinnacle: 'pinnacle' };
  return MAP[key] || key;
}

function transformOddsApiResponse(events) {
  return events.map(event => {
    const markets = {};
    for (const bm of event.bookmakers) {
      const bmKey = normalizeBookmakerKey(bm.key);
      for (const market of bm.markets) {
        if (!markets[market.key]) markets[market.key] = { bookmakers: {} };
        if (!markets[market.key].bookmakers[bmKey]) {
          if (market.key === 'h2h') {
            const outcomes = Object.fromEntries(market.outcomes.map(o => [o.name, o.price]));
            markets[market.key].bookmakers[bmKey] = { home: outcomes[event.home_team], draw: outcomes['Draw'], away: outcomes[event.away_team] };
          } else if (market.key === 'btts') {
            const outcomes = Object.fromEntries(market.outcomes.map(o => [o.name.toLowerCase(), o.price]));
            markets[market.key].bookmakers[bmKey] = { yes: outcomes['yes'], no: outcomes['no'] };
          }
        }
      }
    }
    return { id: event.id, sportKey: event.sport_key, homeTeam: event.home_team, awayTeam: event.away_team, league: event.sport_title, commenceTime: event.commence_time, markets };
  });
}

// ── SSE sync : notifie tous les clients connectés quand MongoDB change ───────
const _sseClients = new Set();

// ── MongoDB userdata ─────────────────────────────────────────────────────────
let _mongoClient = null;
async function getMongoDb() {
  if (!process.env.MONGODB_URI) return null;
  if (!_mongoClient) {
    _mongoClient = new MongoClient(process.env.MONGODB_URI);
    await _mongoClient.connect();
  }
  return _mongoClient.db('ia-betting');
}

// ── Watchdog réseau ──────────────────────────────────────────────────────────
// Incident vécu le 11 juillet 2026 : le process a cessé de résoudre TOUS les
// noms de domaine externes (ENOTFOUND simultané sur rotowire/ESPN/football-data),
// probablement le threadpool libuv (résolutions DNS) saturé par la charge de
// scraping concurrente de l'app — sans jamais crasher, donc les alertes se sont
// arrêtées en silence pendant des heures. Mitigé à la racine en relevant
// UV_THREADPOOL_SIZE (package.json). Ce watchdog est le filet de sécurité si ça
// se reproduit : un ping DNS léger toutes les 2 min, log impossible à rater dès
// 3 échecs d'affilée (~6 min). `node --watch` ne redémarre PAS tout seul après
// un crash (seulement sur modif de fichier) — donc pas d'auto-exit ici, juste
// un signal fort pour agir vite (redémarrage manuel : npm run dev).
let _netFailStreak = 0;
let _netLastCheckOk = true;
async function _networkWatchdog() {
  try {
    await Promise.race([
      dnsPromises.lookup('www.espn.com'),
      new Promise((_, rej) => setTimeout(() => rej(new Error('timeout 5s')), 5000)),
    ]);
    if (_netFailStreak >= 3) console.log(`✅ [watchdog] réseau rétabli après ${_netFailStreak} échecs`);
    _netFailStreak = 0;
    _netLastCheckOk = true;
  } catch (e) {
    _netFailStreak++;
    _netLastCheckOk = false;
    if (_netFailStreak === 3) {
      console.error(`🔴🔴🔴 [watchdog] RÉSEAU DNS EN PANNE (${e.message}) — les alertes ne se génèrent probablement plus depuis ~6min. node --watch ne redémarre PAS tout seul : relancer le process (npm run dev).`);
    } else if (_netFailStreak > 3 && _netFailStreak % 5 === 0) {
      console.error(`🔴 [watchdog] réseau toujours en panne (streak ${_netFailStreak}, ${Math.round(_netFailStreak * 2)}min)`);
    }
  }
}

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/api/health', (req, res) => res.json({ ok: true, timestamp: new Date().toISOString(), networkOk: _netLastCheckOk, netFailStreak: _netFailStreak }));

app.get('/api/sync-events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();
  _sseClients.add(res);
  // Heartbeat toutes les 25s pour éviter que le proxy coupe la connexion
  const hb = setInterval(() => { try { res.write(':\n\n'); } catch { clearInterval(hb); } }, 25_000);
  req.on('close', () => { clearInterval(hb); _sseClients.delete(res); });
});

// Données utilisateur synchronisées (alertes, paris, historique)
app.get('/api/userdata', async (req, res) => {
  try {
    const db = await getMongoDb();
    if (!db) return res.json({});
    const doc = await db.collection('userdata').findOne({ _id: 'main' });
    res.json(doc?.data || {});
  } catch (e) {
    console.error('[userdata GET]', e.message);
    res.json({});
  }
});

app.post('/api/userdata', async (req, res) => {
  try {
    const db = await getMongoDb();
    if (!db) return res.json({ ok: false, reason: 'no mongo' });
    const { key, value } = req.body;
    if (!key) return res.status(400).json({ ok: false });
    let toStore = value;
    // Garde-fou serveur (7 juillet 2026) : plusieurs pages frontend (PlaceBetPage/RunningPage) ne
    // travaillent que sur une fenêtre récente de l'historique et réécrivent pourtant la clé entière —
    // un onglet resté ouvert avec un ancien build JS peut donc écraser Mongo même après un correctif
    // côté client (cf. perte des résultats basket du 6 juillet). Point d'écriture unique côté serveur :
    // si la valeur écrite est un tableau d'alertes, un règlement déjà acquis (won/lost/void) absent du
    // nouveau tableau est automatiquement réintégré au lieu d'être perdu.
    // Étendu le 17 juillet 2026 : ça ne couvrait que l'ID ABSENT du tableau entrant. Un onglet resté
    // ouvert des heures (jamais rechargé) renvoie son propre ID avec un statut périmé ('accepted')
    // qui écrase alors un règlement plus récent ('void') — cas réel Jessica Shepard, 3 occurrences.
    // Un règlement terminal (won/lost/void) ne doit donc jamais être regressé par une valeur entrante,
    // que l'ID soit absent OU présent avec un statut différent.
    if (Array.isArray(value) && value.every(v => v && typeof v === 'object' && 'id' in v)) {
      const doc = await db.collection('userdata').findOne({ _id: 'main' });
      const existing = doc?.data?.[key];
      if (Array.isArray(existing)) {
        const TERMINAL = new Set(['won', 'lost', 'void']);
        const existingById = new Map(existing.filter(v => v && v.id != null).map(v => [v.id, v]));
        const incomingIds = new Set(value.map(v => v.id));
        const preserved = existing.filter(v => v && TERMINAL.has(v.status) && !incomingIds.has(v.id));
        const merged = value.map(v => {
          const prev = existingById.get(v.id);
          if (prev && TERMINAL.has(prev.status) && prev.status !== v.status) return prev;
          return v;
        });
        toStore = preserved.length ? [...merged, ...preserved] : merged;
      }
    }
    await db.collection('userdata').updateOne(
      { _id: 'main' },
      { $set: { [`data.${key}`]: toStore, updatedAt: Date.now() } },
      { upsert: true }
    );
    _sseClients.forEach(c => c.write(`data: sync\n\n`));
    res.json({ ok: true });
  } catch (e) {
    console.error('[userdata POST]', e.message);
    res.status(500).json({ ok: false });
  }
});

// Cotes foot — Unibet (scraping) + Betclic (scraping) + Winamax (scraping)
const _mergeFootballBookmaker = (allMatches, sourceOdds, bkKey) => {
  for (const s of sourceOdds) {
    if (!s.homeTeam || !s.awayTeam) continue;
    const existing = allMatches.find(m => fuzzy(m.homeTeam, s.homeTeam) && fuzzy(m.awayTeam, s.awayTeam));
    if (existing) {
      if (s.h2h) {
        if (!existing.markets.h2h) existing.markets.h2h = { bookmakers: {} };
        existing.markets.h2h.bookmakers[bkKey] = s.h2h;
      }
      if (s.btts) {
        if (!existing.markets.btts) existing.markets.btts = { bookmakers: {} };
        existing.markets.btts.bookmakers[bkKey] = s.btts;
      }
      if (s.totals) {
        if (!existing.markets.totals) existing.markets.totals = { bookmakers: {} };
        existing.markets.totals.bookmakers[bkKey] = s.totals;
      }
      if (s.dcbtts) {
        if (!existing.markets.dcbtts) existing.markets.dcbtts = { bookmakers: {} };
        existing.markets.dcbtts.bookmakers[bkKey] = s.dcbtts;
      }
      if (s.dcou) {
        if (!existing.markets.dcou) existing.markets.dcou = { bookmakers: {} };
        existing.markets.dcou.bookmakers[bkKey] = s.dcou;
      }
    } else {
      const markets = {};
      if (s.h2h)    markets.h2h    = { bookmakers: { [bkKey]: s.h2h } };
      if (s.btts)   markets.btts   = { bookmakers: { [bkKey]: s.btts } };
      if (s.totals) markets.totals = { bookmakers: { [bkKey]: s.totals } };
      if (s.dcbtts) markets.dcbtts = { bookmakers: { [bkKey]: s.dcbtts } };
      if (s.dcou)   markets.dcou   = { bookmakers: { [bkKey]: s.dcou } };
      allMatches.push({
        id: `${bkKey}_${s.homeTeam}_${s.awayTeam}`.replace(/\s/g, '_'),
        sportKey: 'soccer',
        homeTeam: s.homeTeam,
        awayTeam: s.awayTeam,
        commenceTime: s.commenceTime,
        markets,
      });
    }
  }
};

// Fallback bookmaker (foot) : certains bookmakers ratent un match un cycle sur deux pour des
// raisons qui n'ont rien à voir avec une vraie absence de cotes :
// - Betclic : le h2h vient de la page de liste par ligue (fiable), mais btts/totals/dcbtts/dcou
//   viennent d'un fetch par match individuel (fetchBetclicFootballExtras, timeout 8s) bien plus
//   sujet aux échecs transitoires (page pas trouvée, marché pas encore posté).
// - Pinnacle : throttle interne de 15 min (PINNACLE_FOOT_MIN_INTERVAL_MS) — si generateBackgroundAlerts
//   et /api/odds déclenchent tous les deux un _refreshOddsCache à moins de 15 min d'intervalle,
//   le 2e renvoie [] pour tout le foot, pas juste un match isolé.
// Dans les deux cas, une donnée absente ce cycle-ci ne veut pas dire "plus de cotes" — sans ce
// fallback, ça faisait clignoter (Betclic) ou disparaître complètement (Pinnacle) les cotes côté
// front (constaté 7 juillet 2026). Même principe que le fallback basket équivalent (ligne ~4808) :
// on réutilise la dernière valeur connue tant qu'elle a moins de 30 min (ODDS_TTL), en conservant
// l'horodatage d'origine pour ne pas prolonger artificiellement sa fraîcheur.
const _fillMissingBookmaker = (allMatches, prevMatches, bkKey) => {
  const now = Date.now();
  const atKey = `_${bkKey}At`;
  for (const m of allMatches) {
    for (const marketType of ['h2h', 'btts', 'totals', 'dcbtts', 'dcou']) {
      if (m.markets?.[marketType]?.bookmakers?.[bkKey]) {
        m[atKey] = m[atKey] || {};
        m[atKey][marketType] = now;
      }
    }
  }
  if (!prevMatches?.length) return;
  // 26 août 2026 — pendant une pause anti-ban connue (_scraperBlockedUntil), le TTL fixe de 30min
  // faisait disparaître des cotes qu'on sait juste ne pas avoir retentées (pas une vraie absence
  // constatée) — un blocage peut durer jusqu'à 6h (BK_BACKOFF_MAX_MS), bien au-delà des 30min.
  // Tant que le blocage dure, on garde la dernière cote connue sans limite d'âge ; dès qu'il se
  // lève, un fetch normal la remplace au cycle suivant, sinon le TTL de 30min reprend la main
  // (vraie absence si le bookmaker ne revient toujours pas une fois le blocage levé).
  const isBlocked = now < (_scraperBlockedUntil[bkKey] || 0);
  for (const m of allMatches) {
    const prev = prevMatches.find(p => fuzzy(p.homeTeam, m.homeTeam) && fuzzy(p.awayTeam, m.awayTeam));
    if (!prev) continue;
    for (const marketType of ['h2h', 'btts', 'totals', 'dcbtts', 'dcou']) {
      if (m.markets?.[marketType]?.bookmakers?.[bkKey]) continue;
      const prevBk = prev.markets?.[marketType]?.bookmakers?.[bkKey];
      if (!prevBk) continue;
      const staleAt = prev[atKey]?.[marketType] ?? 0;
      if (!isBlocked && now - staleAt > 30 * 60 * 1000) continue;
      m.markets[marketType] = m.markets[marketType] || { bookmakers: {} };
      m.markets[marketType].bookmakers[bkKey] = prevBk;
      m[atKey] = m[atKey] || {};
      m[atKey][marketType] = staleAt;
    }
  }
};

// Marque la tendance (hausse/baisse) de chaque cote par rapport au cache précédent
// — affichée en flèche ▲/▼ dans FootballOddsBox
const _computeOddsTrends = (newMatches, prevMatches) => {
  if (!prevMatches?.length) return;
  for (const m of newMatches) {
    const prev = prevMatches.find(p => fuzzy(p.homeTeam, m.homeTeam) && fuzzy(p.awayTeam, m.awayTeam));
    if (!prev) continue;
    for (const [marketType, market] of Object.entries(m.markets)) {
      const prevBks = prev.markets?.[marketType]?.bookmakers;
      if (!prevBks) continue;
      for (const [bk, odds] of Object.entries(market.bookmakers)) {
        const prevOdds = prevBks[bk];
        if (!prevOdds) continue;
        for (const [outcome, val] of Object.entries(odds)) {
          if (val !== null && typeof val === 'object') {
            // totals : { '1.5': { over, under }, '2.5': {...} }
            const prevLine = prevOdds[outcome];
            if (!prevLine) continue;
            for (const [side, sideVal] of Object.entries(val)) {
              const prevVal = prevLine[side];
              if (typeof sideVal !== 'number' || typeof prevVal !== 'number' || sideVal === prevVal) continue;
              market.trends ??= {};
              market.trends[bk] ??= {};
              market.trends[bk][outcome] ??= {};
              market.trends[bk][outcome][side] = sideVal > prevVal ? 'up' : 'down';
            }
          } else {
            const prevVal = prevOdds[outcome];
            if (typeof val !== 'number' || typeof prevVal !== 'number' || val === prevVal) continue;
            market.trends ??= {};
            market.trends[bk] ??= {};
            market.trends[bk][outcome] = val > prevVal ? 'up' : 'down';
          }
        }
      }
    }
  }
};

// 26 août 2026 — _refreshOddsCache() déclenche fetchBetclicOdds(), qui lance jusqu'à des
// centaines de requêtes "extras" par match (BTTS/O-U/DC détaillés, cf. fetchBetclicFootballExtras)
// en parallèle (jusqu'à 4 à la fois, chacune pouvant timeouter 20s) — une charge soutenue sur le
// process. Découvert en creusant "Outrights Betclic cassé depuis le 3 août" : le scraper Outrights
// (Playwright, communication par pipe avec un sous-processus Chromium séparé) plantait avec
// `browserContext.newPage: Target page, context or browser has been closed` systématiquement
// quand il tournait PENDANT cette rafale — le process saturé fait perdre la connexion au
// navigateur, qui se retrouve considéré "fermé" sans que rien ne l'ait fermé explicitement.
// Ce flag fait attendre le scraper Outrights (rare, TTL 3h) que le rafraîchissement des cotes de
// matchs (fréquent, ~20min) soit terminé, plutôt que l'inverse — rien ne doit ralentir le cycle
// le plus fréquent.
let _oddsRefreshInProgress = false;
// 27 août 2026 — voir fetchBetclicOutrights() : exclusion mutuelle dans l'AUTRE sens, sinon un
// cycle odds-refresh qui démarre pendant qu'Outrights scrape encore recrashe le navigateur Playwright
// exactement pareil (reproduit en direct le 27, le fix à sens unique du 26 août ne suffisait pas).
let _outrightsScrapingInProgress = false;

async function _refreshOddsCache() {
  for (let waited = 0; _outrightsScrapingInProgress && waited < 5 * 60_000; waited += 2000) {
    await new Promise(res => setTimeout(res, 2000));
  }
  _oddsRefreshInProgress = true;
  try {
    return await _refreshOddsCacheInner();
  } finally {
    _oddsRefreshInProgress = false;
  }
}

async function _refreshOddsCacheInner() {
  const [ubOdds, bcOdds, wmOdds, pinOdds] = await Promise.all([
    fetchUnibetFootballOdds().catch(() => []),
    fetchBetclicOdds().catch(() => []),
    fetchWinamaxOdds().catch(() => []),
    fetchPinnacleAllFootball().catch(() => []),
  ]);

  _updateScraper('unibet_foot',  Array.isArray(ubOdds) && ubOdds.length > 0);
  _updateScraper('betclic_foot', Array.isArray(bcOdds) && bcOdds.length > 0);
  _updateScraper('winamax_foot', Array.isArray(wmOdds) && wmOdds.length > 0);
  // Pinnacle est passif par rapport au cycle (throttle interne 15min, retourne [] sans scraper
  // si trop tôt) — ne pas marquer "ok=false" sur un cycle simplement throttlé, seulement sur un
  // vrai échec de scraping. On distingue via _outrightAttempts.pinnacleFootCdm (mis à jour
  // uniquement quand une tentative réelle a eu lieu, pas sur un retour anticipé throttlé).
  if (Date.now() - _outrightAttempts.pinnacleFootCdm < 60_000) {
    _updateScraper('pinnacle_foot', Array.isArray(pinOdds) && pinOdds.length > 0);
  }

  const allMatches = [];
  _mergeFootballBookmaker(allMatches, ubOdds, 'unibet');
  _mergeFootballBookmaker(allMatches, bcOdds, 'betclic');
  _mergeFootballBookmaker(allMatches, wmOdds, 'winamax');
  _mergeFootballBookmaker(allMatches, pinOdds, 'pinnacle');

  const prevMatches = _oddsCache.data?.matches || [];
  _fillMissingBookmaker(allMatches, prevMatches, 'betclic');
  _fillMissingBookmaker(allMatches, prevMatches, 'pinnacle');
  // Unibet ajouté le 14 août 2026 — même raisonnement que Betclic/Pinnacle ci-dessus : le fetch par
  // page de match individuelle (~650 Ko/page, jusqu'à 180 par cycle) timeoute sur une bonne partie
  // des matchs à chaque cycle (cf. log 'unibet: X/Y pages en échec' ajouté au même moment dans
  // fetchUnibetFootballOdds) sans que ce soit une vraie absence de cote — sans ce fallback, la
  // couverture Unibet affichée dépendait entièrement du sous-ensemble qui passait CE cycle-ci,
  // alors qu'elle converge bien plus haut sur 2-3 cycles en réutilisant la dernière valeur connue.
  _fillMissingBookmaker(allMatches, prevMatches, 'unibet');

  _computeOddsTrends(allMatches, _oddsCache.data?.matches);

  // Gèle les cotes au coup d'envoi : un match toujours présent dans le scrape après son
  // commenceTime n'est plus pré-match mais live (in-play) — ses cotes deviennent erratiques
  // (ex: 1.00/40/100 quand un favori prend le large) et ne doivent plus écraser la dernière
  // capture pré-match. Avant ce fix, seul un match totalement *absent* du scrape était figé —
  // un match qui restait visible en live (cas Canada-Qatar, 19 juin 2026) continuait à être
  // rafraîchi indéfiniment avec des cotes in-play affichées comme si elles étaient pré-match.
  const now = Date.now();
  const frozenAllMatches = allMatches.map(m => {
    const kickoff = m.commenceTime ? new Date(m.commenceTime).getTime() : NaN;
    if (!Number.isFinite(kickoff) || kickoff > now) return m; // pas encore commencé (ou date inconnue) : cotes live normales
    const prev = prevMatches.find(p => fuzzy(p.homeTeam, m.homeTeam) && fuzzy(p.awayTeam, m.awayTeam));
    if (prev?.frozen) return prev; // déjà figé un cycle précédent : on garde la même capture
    if (prev) return { ...prev, frozen: true, frozenAt: now }; // 1ère détection post-coup d'envoi : figeles dernières cotes pré-match connues
    return { ...m, frozen: true, frozenAt: now }; // jamais vu avant le coup d'envoi (ex: redémarrage serveur en cours de match) : on figeles cotes live actuelles, mieux que rien
  });
  allMatches.length = 0;
  allMatches.push(...frozenAllMatches);

  // Conserve les cotes pré-match des matchs disparus du scrape (= passés en live/terminé)
  // pendant FROZEN_RETENTION_MS, marquées `frozen: true` pour affichage "cotes pré-match" côté front.
  // Ignoré si le scrape a totalement échoué (sinon tout le cache serait marqué figé à tort).
  const scrapeOk = ubOdds.length > 0 || bcOdds.length > 0 || wmOdds.length > 0;
  if (scrapeOk) {
    // Fix 25 août 2026 (demande explicite utilisateur, cas réel LOSC-PSG : "Odds N/D" affiché alors
    // que les cotes existaient 2 minutes plus tôt) — un match FUTUR totalement absent d'un cycle de
    // scrape (les 4 sources ratent le même match en même temps — rare mais arrive, ex: rate-limit
    // ponctuel) disparaissait intégralement de la liste jusqu'au cycle suivant. Contrairement au
    // fallback par-bookmaker (_fillMissingBookmaker ci-dessus), qui ne peut rien faire pour un match
    // qui n'a même pas d'entrée du tout cette passe. On tamponne maintenant `_lastSeenAt` sur chaque
    // match trouvé CE cycle, pour pouvoir retenir la dernière capture connue d'un match qui disparaît
    // totalement pendant ODDS_TTL (30min, même fenêtre que le fallback par-bookmaker) — SANS
    // `frozen:true` (réservé au vrai coup d'envoi passé, sinon la carte afficherait à tort "cotes
    // pré-match" pour un simple trou de scraping sur un match qui n'a même pas commencé).
    for (const m of allMatches) m._lastSeenAt = now;
    // 3h → 48h (29 août 2026, demande explicite — "comme le basket, que le dernier cycle se fige
    // pour qu'on ait accès à l'historique des cotes après le match"). Depuis le fix "Match
    // introuvable" du même jour, un match terminé reste consultable jusqu'à 48h (même fenêtre que
    // la CDM) — mais ses cotes gelées disparaissaient au bout de 3h seulement, laissant la fiche
    // afficher "Odds N/D" bien avant que le match ne redevienne lui-même introuvable. Alignées sur
    // la même fenêtre pour que les deux durées de vie coïncident.
    const FROZEN_RETENTION_MS = 48 * 60 * 60 * 1000; // 48h
    for (const prev of prevMatches) {
      const stillThere = allMatches.some(m => fuzzy(m.homeTeam, prev.homeTeam) && fuzzy(m.awayTeam, prev.awayTeam));
      if (stillThere) continue;
      const prevKickoff = prev.commenceTime ? new Date(prev.commenceTime).getTime() : NaN;
      if (Number.isFinite(prevKickoff) && prevKickoff <= now) {
        const frozenAt = prev.frozenAt ?? now;
        if (now - frozenAt > FROZEN_RETENTION_MS) continue;
        allMatches.push({ ...prev, frozen: true, frozenAt });
      } else {
        const lastSeenAt = prev._lastSeenAt ?? now;
        if (now - lastSeenAt > ODDS_TTL) continue;
        allMatches.push({ ...prev, _lastSeenAt: lastSeenAt });
      }
    }
  }

  if (allMatches.length > 0) {
    allMatches.sort((a, b) => new Date(a.commenceTime) - new Date(b.commenceTime));
    const sources = [ubOdds.length ? 'unibet' : '', bcOdds.length ? 'betclic' : '', wmOdds.length ? 'winamax' : ''].filter(Boolean).join('+');
    const result = { matches: allMatches, count: allMatches.length, source: sources };
    _oddsCache = { data: result, ts: Date.now() };
    _saveOddsCacheToDisk(result);
    return result;
  }
  if (_oddsCache.data) return _oddsCache.data;
  return { matches: [], count: 0, source: 'none' };
}

app.get('/api/odds', async (req, res) => {
  const forceRefresh = req.query.refresh === '1';

  if (!forceRefresh && _oddsCache.data && Date.now() - _oddsCache.ts < ODDS_TTL) {
    return res.json(_oddsCache.data);
  }

  // Cache présent mais expiré : on le sert tel quel et on rafraîchit en arrière-plan
  // (évite de faire attendre l'utilisateur derrière le scraping + jitter anti-ban)
  if (!forceRefresh && _oddsCache.data) {
    _refreshInBackground('odds', _refreshOddsCache);
    return res.json(_oddsCache.data);
  }

  // Pas de cache du tout (cold start) ou refresh forcé explicitement : on attend le résultat
  try {
    return res.json(await _refreshOddsCache());
  } catch (err) {
    if (_oddsCache.data) return res.json(_oddsCache.data);
    res.status(500).json({ error: 'Failed to fetch odds', message: err.message });
  }
});

function _buildMergedCompetitions(betclicData, pinnacleData, pmuData) {
  const competitions = {};
  for (const [key, comp] of Object.entries(betclicData || {})) {
    const pinnMap = {};
    for (const t of (pinnacleData[key] || [])) pinnMap[normPinnacleTeam(t.name)] = t.odds;
    const pmuMap = {};
    for (const t of (pmuData[key] || [])) pmuMap[normPmuTeam(t.name)] = t.odds;
    competitions[key] = {
      label: comp.label, sport: comp.sport, updatedAt: comp.updatedAt,
      teams: comp.teams.map(t => {
        const books = { betclic: t.odds };
        const pinnOdds = pinnMap[normPinnacleTeam(t.name)];
        const pmuOdds  = pmuMap[normPmuTeam(t.name)];
        if (pinnOdds != null) books.pinnacle = pinnOdds;
        if (pmuOdds  != null) books.pmu = pmuOdds;
        return { name: t.name, books };
      }),
    };
  }
  return competitions;
}

// Fusion des marchés Top N/Podium/Relégation/Division/Conférence par compétition (28 juillet
// 2026, étendu à Pinnacle le 30 juillet) — proche de _buildMergedCompetitions mais indexée par
// marché plutôt qu'une seule liste "Vainqueur". Pinnacle n'expose que Vainqueur + parfois
// Conférence Est/Ouest (cf. PINNACLE_OUTRIGHT_LEAGUES/_classifyPinnacleSpecialDescription),
// jamais de Top N/Podium/Relégation/Division — ses marchés sont un sous-ensemble de ceux de
// Betclic/PMU, jamais la seule source sur une clé donnée. Un marché n'apparaît dans le résultat
// que s'il a au moins une source.
function _buildMergedCompetitionMarkets(betclicMarkets, pmuMarkets, pinnacleMarkets) {
  const marketKeys = new Set([...Object.keys(betclicMarkets || {}), ...Object.keys(pmuMarkets || {}), ...Object.keys(pinnacleMarkets || {})]);
  const markets = {};
  for (const marketKey of marketKeys) {
    const betclicTeams = betclicMarkets?.[marketKey] || [];
    const pmuTeams = pmuMarkets?.[marketKey] || [];
    const pinnTeams = pinnacleMarkets?.[marketKey] || [];
    const pmuMap = {};
    for (const t of pmuTeams) pmuMap[normPmuTeam(t.name)] = t.odds;
    const pinnMap = {};
    for (const t of pinnTeams) pinnMap[normPinnacleTeam(t.name)] = t.odds;

    const teams = betclicTeams.map(t => {
      const books = { betclic: t.odds };
      const pmuOdds = pmuMap[normPmuTeam(t.name)];
      const pinnOdds = pinnMap[normPinnacleTeam(t.name)];
      if (pmuOdds != null) { books.pmu = pmuOdds; delete pmuMap[normPmuTeam(t.name)]; }
      if (pinnOdds != null) { books.pinnacle = pinnOdds; delete pinnMap[normPinnacleTeam(t.name)]; }
      return { name: t.name, books };
    });
    // Équipes vues seulement chez PMU ou Pinnacle (pas de correspondance Betclic sur ce marché précis)
    for (const t of pmuTeams) {
      if (pmuMap[normPmuTeam(t.name)] == null) continue;
      teams.push({ name: t.name, books: { pmu: t.odds } });
    }
    for (const t of pinnTeams) {
      if (pinnMap[normPinnacleTeam(t.name)] == null) continue;
      teams.push({ name: t.name, books: { pinnacle: t.odds } });
    }
    if (teams.length) markets[marketKey] = teams.sort((a, b) => (a.books.betclic ?? a.books.pmu ?? a.books.pinnacle) - (b.books.betclic ?? b.books.pmu ?? b.books.pinnacle));
  }
  return markets;
}

let _outrightsRefreshing = false;
// Un vrai scrape par source est bloqué pendant 15min après la dernière tentative (garde-fou
// anti-ban) — exposé au frontend pour afficher un minuteur plutôt que de laisser croire qu'un
// clic sur "Rafraîchir" relance toujours un vrai scraping.
function _outrightsNextRefreshAt() {
  return Math.max(
    _outrightAttempts.betclic   + BETCLIC_OUTRIGHT_MIN_INTERVAL_MS,
    _outrightAttempts.pinnacle  + PINNACLE_OUTRIGHT_MIN_INTERVAL_MS,
    _outrightAttempts.pmu       + PMU_OUTRIGHT_MIN_INTERVAL_MS,
  );
}
app.get('/api/outrights', async (req, res) => {
  if (req.query.refresh === '1') { _outrightsCache.ts = 0; _pinnacleOutrightsCache.ts = 0; _pmuOutrightsCache.ts = 0; }

  const hasCache = _outrightsCache.data && Object.keys(_outrightsCache.data).length > 0;
  const cacheStale = Date.now() - _outrightsCache.ts > OUTRIGHTS_TTL;

  // Répondre immédiatement avec le cache existant, refresh en arrière-plan si périmé
  if (hasCache && req.query.refresh !== '1') {
    const competitions = _buildMergedCompetitions(
      _outrightsCache.data,
      _pinnacleOutrightsCache.data || {},
      _pmuOutrightsCache.data || {},
    );
    const blockedUntil = Date.now() < _scraperBlockedUntil.betclic ? _scraperBlockedUntil.betclic : null;
    res.json({ competitions, blockedUntil, stale: cacheStale, nextRefreshAt: _outrightsNextRefreshAt() });

    if (cacheStale && !_outrightsRefreshing) {
      _outrightsRefreshing = true;
      Promise.all([getOutrights(), getPinnacleOutrights(), getPmuOutrights()])
        .catch(() => {})
        .finally(() => { _outrightsRefreshing = false; });
    }
    return;
  }

  // Pas de cache — attendre le scrape initial (1ère charge seulement)
  try {
    const [betclicData, pinnacleData, pmuData] = await Promise.all([getOutrights(), getPinnacleOutrights(), getPmuOutrights()]);
    const competitions = _buildMergedCompetitions(betclicData, pinnacleData, pmuData);
    const blockedUntil = Date.now() < _scraperBlockedUntil.betclic ? _scraperBlockedUntil.betclic : null;
    res.json({ competitions, blockedUntil, nextRefreshAt: _outrightsNextRefreshAt() });
  } catch (err) {
    // 26 août 2026 — cette exception était totalement silencieuse (pas de console.error, pas de
    // _bgLog) : renvoyait {competitions:{}} sans jamais dire pourquoi. Trouvé en creusant "Betclic
    // outrights vide depuis le 3 août" — nécessaire pour voir la vraie erreur au lieu de deviner.
    console.error('[/api/outrights]', err.message);
    _bgLog.push(`outrights route error: ${err.message}`);
    res.json({ competitions: {}, blockedUntil: null, nextRefreshAt: _outrightsNextRefreshAt() });
  }
});

// Marchés Top N / Podium / Relégation pour une seule compétition (28 juillet 2026) — additif,
// ne touche pas /api/outrights (marché Vainqueur seul, consommé par generateOutrightAlerts et les
// alertes outright_model/outright_gap déjà en prod). Lit _outrightMarketsCache (alimenté en
// side-effect par fetchBetclicOutrights/fetchPmuOutrights) — appeler getOutrights()/getPmuOutrights()
// ici ne fait que respecter leur propre TTL 3h / anti-ban, ça ne force jamais un scrape en plus.
// Fusion des marchés "par équipe" (30 juillet 2026) — proche de _buildMergedCompetitionMarkets
// mais indexée par équipe plutôt que classée par cote (pas de notion de "meilleure cote en tête",
// juste over/under ou oui/non par bookmaker). Pinnacle n'a pas ces marchés, pas inclus ici.
function _buildMergedTeamProps(betclicProps, pmuProps) {
  const result = {};
  const propTypes = new Set([...Object.keys(betclicProps || {}), ...Object.keys(pmuProps || {})]);
  for (const propType of propTypes) {
    const betclicTeams = betclicProps?.[propType] || {};
    const pmuTeams = pmuProps?.[propType] || {};
    const teamNames = new Set([...Object.keys(betclicTeams), ...Object.keys(pmuTeams)]);
    const merged = {};
    for (const team of teamNames) {
      const bc = betclicTeams[team];
      const pmu = pmuTeams[team];
      const line = bc?.line ?? pmu?.line ?? null;
      const books = {};
      if (bc)  books.betclic = propType === 'win_total' ? { over: bc.over, under: bc.under } : { yes: bc.yes, no: bc.no };
      if (pmu) books.pmu     = propType === 'win_total' ? { over: pmu.over, under: pmu.under } : { yes: pmu.yes, no: pmu.no };
      merged[team] = { line, books };
    }
    if (Object.keys(merged).length) result[propType] = merged;
  }
  return result;
}

app.get('/api/outrights/:compKey/markets', async (req, res) => {
  const { compKey } = req.params;
  const target = BETCLIC_OUTRIGHT_TARGETS.find(t => t.key === compKey);
  if (!target) return res.status(404).json({ error: 'Compétition inconnue' });

  try {
    await Promise.all([getOutrights(), getPmuOutrights(), getPinnacleOutrights()]);
  } catch {}

  const markets = _buildMergedCompetitionMarkets(
    _outrightMarketsCache.betclic[compKey] || {},
    _outrightMarketsCache.pmu[compKey] || {},
    _outrightMarketsCache.pinnacle[compKey] || {},
  );
  const teamProps = _buildMergedTeamProps(
    _outrightTeamPropsCache.betclic[compKey] || {},
    _outrightTeamPropsCache.pmu[compKey] || {},
  );
  res.json({ label: target.label, sport: target.sport, markets, teamProps });
});


// ── ESPN (NBA) — aucune clé requise ──────────────────────────────────────────
const ESPN_NBA        = 'https://site.api.espn.com/apis/site/v2/sports/basketball/nba/teams';
const ESPN_ATHLETE    = 'https://site.web.api.espn.com/apis/common/v3/sports/basketball/nba/athletes';
const ESPN_SCOREBOARD = 'https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard';
const ESPN_WNBA          = 'https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/teams';
const ESPN_WNBA_ATH      = 'https://site.web.api.espn.com/apis/common/v3/sports/basketball/wnba/athletes';
const ESPN_WNBA_SB       = 'https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/scoreboard';
const ESPN_WNBA_STATS    = 'https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/teams';
const ESPN_WNBA_STANDING = 'https://site.api.espn.com/apis/v2/sports/basketball/wnba/standings';
const ESPN_WNBA_LEADERS  = 'https://site.api.espn.com/apis/site/v2/sports/basketball/wnba/leaders';
const ESPN_WNBA_CORE     = `https://sports.core.api.espn.com/v2/sports/basketball/leagues/wnba/seasons/${new Date().getFullYear()}/types/2/athletes`;
const WNBA_SEASON        = new Date().getFullYear();
const now = new Date();
const ESPN_SEASON = now.getMonth() >= 9 ? now.getFullYear() + 1 : now.getFullYear();
const _espnCache    = {};
// Persisté sur disque (12 juillet 2026) — un match qui passe en live disparaît de la page
// listing Unibet (cf. fetchUnibetBasketData) ; sans l'URL retenue avant le coup d'envoi, plus
// aucun moyen de retrouver la page une fois live. Purement en mémoire jusqu'ici, cette table
// était vidée à chaque redémarrage du process (node --watch), perdant définitivement les cotes
// Unibet de tout match déjà en live au redémarrage — cas réel : Las Vegas Aces vs Phoenix Mercury.
const _ubMatchUrlCache = {};   // { `${league}_${normHome}_${normAway}` → matchPath }
try { if (existsSync(UB_MATCH_URL_CACHE_FILE)) Object.assign(_ubMatchUrlCache, JSON.parse(readFileSync(UB_MATCH_URL_CACHE_FILE, 'utf8'))); } catch {}
const _saveUbMatchUrlCache = () => { try { writeFileSync(UB_MATCH_URL_CACHE_FILE, JSON.stringify(_ubMatchUrlCache), 'utf8'); } catch {} };
const CACHE_6H      = 6 * 60 * 60 * 1000;
const CACHE_24H      = 24 * 60 * 60 * 1000;
// Charge les rosters NBA/WNBA depuis le disque dès que _espnCache + CACHE_6H sont disponibles
_loadEspnPlayersFromDisk();
const CACHE_30MIN   = 30 * 60 * 1000;
const CACHE_5MIN    = 5 * 60 * 1000;

let _scoreboardCache = { data: null, ts: 0 };

function normalizeGame(ev) {
  try {
    const comp = ev.competitions[0];
    const home = comp.competitors.find(c => c.homeAway === 'home');
    const away = comp.competitors.find(c => c.homeAway === 'away');
    const recH = home?.records?.[0]?.summary || '';
    const recA = away?.records?.[0]?.summary || '';
    const [hw, hl] = recH.split('-').map(Number);
    const [aw, al] = recA.split('-').map(Number);
    const homeScore = home?.score != null ? parseInt(home.score) : null;
    const awayScore = away?.score != null ? parseInt(away.score) : null;
    const note         = comp.notes?.[0]?.headline || '';
    const seriesSummary = comp.series?.summary || '';
    return {
      id:           ev.id,
      date:         ev.date,
      status:       comp.status?.type?.name || 'STATUS_SCHEDULED',
      statusDetail: comp.status?.type?.shortDetail || comp.status?.type?.description || '',
      note,
      seriesSummary,
      venue:        { city: comp.venue?.address?.city || '', name: comp.venue?.fullName || '' },
      home: { name: home?.team?.displayName || '', short: home?.team?.abbreviation || '', logo: home?.team?.logo || '', score: isNaN(homeScore) ? 0 : homeScore, wins: hw || 0, losses: hl || 0 },
      away: { name: away?.team?.displayName || '', short: away?.team?.abbreviation || '', logo: away?.team?.logo || '', score: isNaN(awayScore) ? 0 : awayScore, wins: aw || 0, losses: al || 0 },
    };
  } catch {
    return null;
  }
}

// ── Playoff patch — auto-update scores/rounds for completed games ─────────────
const _patchCache = { data: null, ts: 0 };
app.get('/api/nba/playoff-patch', async (req, res) => {
  if (_patchCache.data && Date.now() - _patchCache.ts < CACHE_5MIN) return res.json(_patchCache.data);
  try {
    const seen = new Set();
    const allEvents = [];
    for (let i = -8; i <= 3; i++) {
      const dateStr = new Date(Date.now() + i * 86400000).toISOString().slice(0,10).replace(/-/g,'');
      const r = await fetch(`${ESPN_SCOREBOARD}?dates=${dateStr}&limit=50`);
      if (!r.ok) continue;
      for (const ev of (await r.json()).events || []) {
        if (seen.has(ev.id)) continue;
        seen.add(ev.id);
        allEvents.push(ev);
      }
    }
    const ESPN_NORM = { SA:'SAS', NY:'NYK', GS:'GSW', NO:'NOP', UT:'UTA' };
    const normAbbr = a => ESPN_NORM[a?.toUpperCase()] || a?.toUpperCase() || '';
    const patches = [];
    for (const ev of allEvents) {
      const g = normalizeGame(ev);
      if (!g) continue;
      if (!g.status.includes('STATUS_FINAL')) continue;
      const comp = ev.competitions?.[0];
      const series = comp?.series;
      const seriesTitle = series?.title || '';          // "Western Conference Finals - Game 3"
      const seriesSummary = series?.summary || '';      // "OKC leads, 2-1"
      const seriesWins = {};
      for (const sc of (series?.competitors || [])) {
        const abbr = normAbbr(sc.team?.abbreviation);
        if (abbr) seriesWins[abbr] = sc.wins || 0;
      }
      const gameNumMatch = seriesTitle.match(/Game\s*(\d+)/i);
      patches.push({
        espnId:        g.id,
        date:          g.date,
        home:          normAbbr(g.home.short),
        away:          normAbbr(g.away.short),
        homeName:      g.home.name,
        awayName:      g.away.name,
        homeScore:     g.home.score,
        awayScore:     g.away.score,
        seriesSummary,
        seriesWins,
        gameNum:       gameNumMatch ? parseInt(gameNumMatch[1]) : null,
      });
    }

    // Matchs à venir (playoffs uniquement) — génèrent des fixtures auto dans useFixtures
    const upcoming = [];
    for (const ev of allEvents) {
      const g = normalizeGame(ev);
      if (!g) continue;
      if (!g.status.includes('STATUS_SCHEDULED')) continue;
      const comp  = ev.competitions?.[0];
      const note  = comp?.notes?.[0]?.headline || comp?.series?.title || comp?.note || '';
      if (!note.match(/finals|round|playoff/i)) continue; // playoffs seulement
      const series = comp?.series;
      const seriesSummary = series?.summary || '';
      const gameNumMatch  = note.match(/Game\s*(\d+)/i);
      upcoming.push({
        espnId:       g.id,
        date:         g.date,
        home:         normAbbr(g.home.short),
        away:         normAbbr(g.away.short),
        homeName:     g.home.name,
        awayName:     g.away.name,
        note,
        seriesSummary,
        gameNum:      gameNumMatch ? parseInt(gameNumMatch[1]) : null,
        venue:        g.venue?.name ? { name: g.venue.name, city: g.venue.city } : null,
      });
    }

    const result = { patches, upcoming };
    _patchCache.data = result;
    _patchCache.ts = Date.now();
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/nba/scoreboard', async (req, res) => {
  const hasLive = _scoreboardCache.data?.games?.some(g => g.status === 'STATUS_IN_PROGRESS');
  const ttl     = hasLive ? 30_000 : CACHE_5MIN;
  if (_scoreboardCache.data && Date.now() - _scoreboardCache.ts < ttl)
    return res.json(_scoreboardCache.data);
  try {
    const allEvents = [];
    // Today sans ?dates → scores live temps réel
    const todayResp = await fetch(`${ESPN_SCOREBOARD}?limit=50`);
    if (todayResp.ok) allEvents.push(...((await todayResp.json()).events || []));
    // J-1 à J+3 par date explicite (couvre les matchs du soir en heure locale US)
    for (let i = -1; i <= 3; i++) {
      const d = new Date(Date.now() + i * 86400000);
      const dateStr = d.toISOString().slice(0, 10).replace(/-/g, '');
      const resp = await fetch(`${ESPN_SCOREBOARD}?dates=${dateStr}&limit=50`);
      if (!resp.ok) continue;
      allEvents.push(...((await resp.json()).events || []));
    }
    // Dédoublonnage par id
    const seen = new Set();
    const unique = allEvents.filter(ev => { if (seen.has(ev.id)) return false; seen.add(ev.id); return true; });
    const games = unique.map(normalizeGame).filter(Boolean);
    _scoreboardCache = { data: { games }, ts: Date.now() };
    _updateScraper('espn', games.length > 0);
    res.json({ games });
  } catch (err) {
    _updateScraper('espn', false);
    // Retourne le cache périmé plutôt qu'une erreur si ESPN est down
    if (_scoreboardCache.data) return res.json(_scoreboardCache.data);
    res.status(500).json({ error: err.message });
  }
});

