// Suivi des "presque-alertes" (19 juillet 2026) — l'utilisateur demande une vraie réponse chiffrée
// sur "est-ce que le seuil de 77% est le bon" avant d'y toucher (cf. le fix rebonds du même jour,
// décidé sur 13 vrais paris plutôt qu'au pif). Enregistre tout candidat props (NBA+WNBA, toutes
// stats) qui approche le seuil sans le franchir (floor-20 à floor exclu), puis règle le résultat
// réel une fois le match terminé (même mécanisme que _logProjectionAccuracy) — accumule un
// échantillon de validation bien plus grand que les seules alertes réellement acceptées.
let _nearMissCandidates = [];
try {
  if (existsSync(NEAR_MISS_FILE)) _nearMissCandidates = JSON.parse(readFileSync(NEAR_MISS_FILE, 'utf8')).rows || [];
} catch {}
function _saveNearMiss() {
  try { writeFileSync(NEAR_MISS_FILE, JSON.stringify({ rows: _nearMissCandidates }), 'utf8'); } catch {}
}
// Filtre de bande [floor-20pts, floor) retiré le 28 juillet 2026 — demande explicite de l'utilisateur
// (déjà formulée le 24 juillet : "des résultats solides sur tous les marchés d'ici un mois") de
// logger sur toute la plage de probabilité, comme le fait déjà MLB, pour pouvoir déterminer le
// seuil optimal par rentabilité (proba réelle × cote) plutôt que juste vérifier si le seuil actuel
// est bien placé. `floor` reste stocké (utile pour savoir quel seuil était actif au moment du calcul).
// Cote ajoutée le 28 juillet 2026 — sans elle on peut juger la calibration (le % annoncé est-il
// juste) mais pas la rentabilité (% réel × cote). Les deux analyses seront à distinguer clairement
// au bilan : "le % est-il bon" vs "est-ce rentable au % réel obtenu".
// Fix 29 août 2026, demande explicite — avant ce fix, une fois un candidat loggé une 1ère fois
// (même id = même match+joueuse+stat+direction+ligne), tous les cycles suivants (toutes les 20min,
// parfois sur plusieurs jours avant le match) étaient ignorés purement et simplement : la probabilité
// gelée dans l'archive était celle de la toute PREMIÈRE fois vue, souvent calculée tôt avec moins
// d'infos disponibles (blessures pas encore connues, forme pas encore à jour) — pas celle, plus
// fiable, du dernier cycle juste avant le match, qui est ce sur quoi une vraie alerte se serait basée.
// Le candidat reste le même (même id, même joueuse/match/stat suivis), seule sa probabilité (et les
// champs qui en dépendent) se met à jour à chaque cycle tant que le match n'a pas eu lieu — la
// dernière valeur avant le coup d'envoi est celle qui compte pour juger la calibration du modèle.
// Garde-fou : un candidat déjà réglé (`status` 'won'/'lost'/'void') n'est JAMAIS modifié rétroactivement,
// seuls les candidats encore 'pending' (match pas encore joué) sont mis à jour.
function _logNearMissCandidate({ gameId, league, player, stat, direction, line, probability, floor, unibetOdds, betclicOdds, estimate, tags }) {
  const id = `${gameId}_${player}_${stat}_${direction}_${line}`;
  const existing = _nearMissCandidates.find(c => c.id === id);
  if (existing) {
    if (existing.status === 'pending') {
      existing.probability = +(probability * 100).toFixed(1);
      existing.floor = +(floor * 100).toFixed(1);
      existing.unibetOdds = unibetOdds ?? null;
      existing.betclicOdds = betclicOdds ?? null;
      existing.estimate = estimate ?? null;
      if (tags?.length) existing.tags = tags;
    }
    return;
  }
  _nearMissCandidates.push({ id, gameId, league, player, stat, direction, line, probability: +(probability * 100).toFixed(1), floor: +(floor * 100).toFixed(1), unibetOdds: unibetOdds ?? null, betclicOdds: betclicOdds ?? null, estimate: estimate ?? null, ...(tags?.length ? { tags } : {}), status: 'pending', savedAt: Date.now() });
}
async function _resolveNearMissCandidates() {
  const base = `http://localhost:${process.env.PORT || 3001}`;
  const pending = _nearMissCandidates.filter(c => c.status === 'pending');
  if (!pending.length) return;
  const byGame = {};
  pending.forEach(c => { (byGame[`${c.league}_${c.gameId}`] ??= []).push(c); });
  for (const key of Object.keys(byGame)) {
    const [league, gameId] = [key.split('_')[0], key.split('_').slice(1).join('_')];
    try {
      const sb = await fetch(`${base}/api/${league}/scoreboard`).then(r => r.ok ? r.json() : null).catch(() => null);
      const game = (sb?.games || []).find(g => String(g.id) === String(gameId));
      if (!game || game.status !== 'STATUS_FINAL') continue;
      const bsUrl = `${base}/api/${league}/boxscore?date=${encodeURIComponent(game.date)}&home=${encodeURIComponent(game.home.short)}&away=${encodeURIComponent(game.away.short)}`;
      const bs = await fetch(bsUrl).then(r => r.ok ? r.json() : null).catch(() => null);
      if (!bs || bs.error) continue;
      const bsKeys = Object.keys(bs).filter(k => !['gameId', 'status', 'homeScore', 'awayScore', 'error'].includes(k));
      const realizedPlayers = bsKeys.flatMap(k => bs[k] || []);
      for (const c of byGame[key]) {
        const r = realizedPlayers.find(x => x.name === c.player);
        if (!r || r.dnp) { c.status = 'void'; continue; }
        let realv = r.stats?.[c.stat];
        if (typeof realv === 'string' && realv.includes('-')) realv = parseInt(realv.split('-')[0]) || 0;
        if (realv == null) { c.status = 'void'; continue; }
        c.actualStat = realv;
        const cleared = c.direction === 'over' ? realv > c.line : realv < c.line;
        c.status = cleared ? 'won' : 'lost';
      }
    } catch {}
  }
  const cutoff = Date.now() - 90 * 86400_000;
  _nearMissCandidates = _nearMissCandidates.filter(c => c.savedAt > cutoff);
  _saveNearMiss();
}
// Vérifie le test plancher rebonds WNBA (voir WNBA_REB_FLOOR_TEST plus bas) — réutilise le near-miss
// existant (déjà loggé pour CHAQUE candidat, floor inclus, résolu automatiquement ci-dessus) plutôt
// que de créer un 2e système de tracking. Un candidat compte pour le test s'il a été évalué avec le
// plancher abaissé (floor===68) ET que sa probabilité l'aurait fait passer (>=68) — donc uniquement
// les alertes qui n'existaient pas avant ce test. ROI = moyenne((cote-1) si gagné, -1 si perdu), avec
// la meilleure cote dispo entre Unibet/Betclic. Sous zéro après un échantillon minimum → retour
// automatique à l'ancien plancher + notif Telegram, décision persistée sur disque (survit à un
// redémarrage).
function _checkWnbaRebFloorTestRollback() {
  if (!_wnbaRebFloorTestActive) return;
  const testFloorPct = Math.round(WNBA_REB_FLOOR_TEST * 100);
  const candidates = _nearMissCandidates.filter(c =>
    c.stat === 'reb' && c.league === 'wnba' && c.floor === testFloorPct &&
    c.probability >= testFloorPct && ['won', 'lost'].includes(c.status) &&
    (c.unibetOdds || c.betclicOdds)
  );
  if (candidates.length < WNBA_REB_FLOOR_TEST_MIN_N) return;
  const rets = candidates.map(c => {
    const odds = Math.max(c.unibetOdds || 0, c.betclicOdds || 0);
    return c.status === 'won' ? odds - 1 : -1;
  });
  const roi = rets.reduce((s, r) => s + r, 0) / rets.length;
  // Décision utilisateur (2 août 2026) : plus de rollback automatique — le test reste actif tel
  // quel, on se contente de prévenir (une seule fois par franchissement, pas à chaque cycle) et la
  // décision d'arrêter revient à l'utilisateur (POST /api/system/wnba-floor-test/reb/end une fois
  // qu'il a tranché).
  if (roi < 0 && !_wnbaRebFloorTestAlerted) {
    _wnbaRebFloorTestAlerted = true;
    _saveWnbaRebFloorTestState();
    const msg = `Test plancher rebonds WNBA : ROI ${(roi * 100).toFixed(1)}% sur ${candidates.length} paris résolus — sous zéro, décision à prendre (rollback vers ${Math.round(WNBA_REB_FLOOR_ORIGINAL * 100)}% ?). Reste actif tant que non arrêté manuellement.`;
    _bgLog.push(msg);
    sendTelegramMessage(`⚠️ ${msg}`).catch(() => {});
  } else if (roi >= 0 && _wnbaRebFloorTestAlerted) {
    _wnbaRebFloorTestAlerted = false;
    _saveWnbaRebFloorTestState();
  }
}
